window.KG_PHRASES = [{"set": 1, "date": "2026-09-27", "topic": "人文历史", "title": "Tea: A Leaf That Travelled the World", "items": [{"p": "much more than", "cn": "远不止，不仅仅是", "eg": "For more than a thousand years, tea has been much more than a drink in China.", "egcn": "茶在中国早已不只是一杯饮料：它从西南山区的药材，变成唐宋时期从宫廷到村落的日常，又沿着丝绸之路随商队走遍世界。让这段旅程成为可能的，不只是贸易，更是好奇心——同一片叶子在不同的土地上被改造成日本茶道、英式奶茶、蒙古酥油茶。今天茶是世界第二大饮品，这条古老的商路也成了文化交流的象征：愿意分享、乐于学习的人和国家，总能在路上遇到朋友。", "src": "Tea: A Leaf That Travelled the World"}, {"p": "together with", "cn": "连同，和……一起", "eg": "During the Tang and Song dynasties, merchants carried tea along the Silk Road, together with silk, porcelain and ideas.", "egcn": "茶在中国早已不只是一杯饮料：它从西南山区的药材，变成唐宋时期从宫廷到村落的日常，又沿着丝绸之路随商队走遍世界。让这段旅程成为可能的，不只是贸易，更是好奇心——同一片叶子在不同的土地上被改造成日本茶道、英式奶茶、蒙古酥油茶。今天茶是世界第二大饮品，这条古老的商路也成了文化交流的象征：愿意分享、乐于学习的人和国家，总能在路上遇到朋友。", "src": "Tea: A Leaf That Travelled the World"}, {"p": "in turn", "cn": "反过来；依次，轮流", "eg": "Foreign visitors were curious about the strange bitter drink and the rituals that surrounded it; Chinese merchants, in turn, were eager to learn about new markets and new tastes.", "egcn": "茶在中国早已不只是一杯饮料：它从西南山区的药材，变成唐宋时期从宫廷到村落的日常，又沿着丝绸之路随商队走遍世界。让这段旅程成为可能的，不只是贸易，更是好奇心——同一片叶子在不同的土地上被改造成日本茶道、英式奶茶、蒙古酥油茶。今天茶是世界第二大饮品，这条古老的商路也成了文化交流的象征：愿意分享、乐于学习的人和国家，总能在路上遇到朋友。", "src": "Tea: A Leaf That Travelled the World"}, {"p": "be curious about", "cn": "对……感到好奇", "eg": "Children are naturally curious about the world around them.", "egcn": "孩子们对周围的世界天生好奇。", "src": "Tea: A Leaf That Travelled the World"}, {"p": "be willing to do sth", "cn": "愿意做某事", "eg": "She was willing to help us move the furniture.", "egcn": "她愿意帮我们搬家具。", "src": "Tea: A Leaf That Travelled the World"}, {"p": "not only ... but (also) ...", "cn": "不仅……而且……（并列结构，注意前后一致）", "eg": "What made this journey possible was not only trade but curiosity.", "egcn": "茶在中国早已不只是一杯饮料：它从西南山区的药材，变成唐宋时期从宫廷到村落的日常，又沿着丝绸之路随商队走遍世界。让这段旅程成为可能的，不只是贸易，更是好奇心——同一片叶子在不同的土地上被改造成日本茶道、英式奶茶、蒙古酥油茶。今天茶是世界第二大饮品，这条古老的商路也成了文化交流的象征：愿意分享、乐于学习的人和国家，总能在路上遇到朋友。", "src": "Tea: A Leaf That Travelled the World"}]}, {"set": 2, "date": "2026-09-28", "topic": "科技（医疗人工智能）", "title": "A Second Pair of Eyes: How AI Helps Doctors", "items": [{"p": "on its own", "cn": "独自地，靠自己（= without help）", "eg": "In recent years, hospitals in many countries have begun to use software that can read some of these images on its own.", "egcn": "医院每天产生海量影像，医生一个人一轮班要看几百张，疲劳的眼睛难免漏掉问题。近年不少医院开始用能自己读片的软件——它不取代医生，而像一双永不疲倦的眼睛。原理是用上百万张带标注的旧影像训练程序，让它学会专家关注的那些模式；新片子进来，它标出可疑处并给出评分。但软件的质量取决于训练数据：如果数据大多来自一个国家或一个年龄段，它对其他人可能表现很差，而且它会“自信地出错”，误导忙碌的医生。所以医院让专科医生始终在回路里——软件建议，人做决定；患者也有权知道机器参与了多少。结论不是“人机对抗”，而是“人机协作”：机器快、不知疲倦、成本低，医生细致、有创造力、有温度，结合起来才能更早发现疾病，也让医生有时间多陪病人。", "src": "A Second Pair of Eyes: How AI Helps Doctors"}, {"p": "a second pair of eyes", "cn": "第二双眼睛（帮忙复核的人）", "eg": "Instead, it acts like a second pair of eyes that never gets sleepy.", "egcn": "医院每天产生海量影像，医生一个人一轮班要看几百张，疲劳的眼睛难免漏掉问题。近年不少医院开始用能自己读片的软件——它不取代医生，而像一双永不疲倦的眼睛。原理是用上百万张带标注的旧影像训练程序，让它学会专家关注的那些模式；新片子进来，它标出可疑处并给出评分。但软件的质量取决于训练数据：如果数据大多来自一个国家或一个年龄段，它对其他人可能表现很差，而且它会“自信地出错”，误导忙碌的医生。所以医院让专科医生始终在回路里——软件建议，人做决定；患者也有权知道机器参与了多少。结论不是“人机对抗”，而是“人机协作”：机器快、不知疲倦、成本低，医生细致、有创造力、有温度，结合起来才能更早发现疾病，也让医生有时间多陪病人。", "src": "A Second Pair of Eyes: How AI Helps Doctors"}, {"p": "as good as", "cn": "和……一样好；几乎等于", "eg": "The programs are only as good as the data they were trained on.", "egcn": "医院每天产生海量影像，医生一个人一轮班要看几百张，疲劳的眼睛难免漏掉问题。近年不少医院开始用能自己读片的软件——它不取代医生，而像一双永不疲倦的眼睛。原理是用上百万张带标注的旧影像训练程序，让它学会专家关注的那些模式；新片子进来，它标出可疑处并给出评分。但软件的质量取决于训练数据：如果数据大多来自一个国家或一个年龄段，它对其他人可能表现很差，而且它会“自信地出错”，误导忙碌的医生。所以医院让专科医生始终在回路里——软件建议，人做决定；患者也有权知道机器参与了多少。结论不是“人机对抗”，而是“人机协作”：机器快、不知疲倦、成本低，医生细致、有创造力、有温度，结合起来才能更早发现疾病，也让医生有时间多陪病人。", "src": "A Second Pair of Eyes: How AI Helps Doctors"}, {"p": "keep sb in the loop", "cn": "让某人知情、参与其中", "eg": "For this reason, hospitals keep a specialist in the loop: the software suggests, the human decides.", "egcn": "医院每天产生海量影像，医生一个人一轮班要看几百张，疲劳的眼睛难免漏掉问题。近年不少医院开始用能自己读片的软件——它不取代医生，而像一双永不疲倦的眼睛。原理是用上百万张带标注的旧影像训练程序，让它学会专家关注的那些模式；新片子进来，它标出可疑处并给出评分。但软件的质量取决于训练数据：如果数据大多来自一个国家或一个年龄段，它对其他人可能表现很差，而且它会“自信地出错”，误导忙碌的医生。所以医院让专科医生始终在回路里——软件建议，人做决定；患者也有权知道机器参与了多少。结论不是“人机对抗”，而是“人机协作”：机器快、不知疲倦、成本低，医生细致、有创造力、有温度，结合起来才能更早发现疾病，也让医生有时间多陪病人。", "src": "A Second Pair of Eyes: How AI Helps Doctors"}, {"p": "play a part (in)", "cn": "起作用，参与（= play a role）", "eg": "Everyone can play a part in keeping the city clean.", "egcn": "每个人都能为保持城市整洁出一份力。", "src": "A Second Pair of Eyes: How AI Helps Doctors"}, {"p": "in charge", "cn": "负责，主管（be in charge of sth）", "eg": "That is a trade worth making, as long as we never forget who is in charge.", "egcn": "医院每天产生海量影像，医生一个人一轮班要看几百张，疲劳的眼睛难免漏掉问题。近年不少医院开始用能自己读片的软件——它不取代医生，而像一双永不疲倦的眼睛。原理是用上百万张带标注的旧影像训练程序，让它学会专家关注的那些模式；新片子进来，它标出可疑处并给出评分。但软件的质量取决于训练数据：如果数据大多来自一个国家或一个年龄段，它对其他人可能表现很差，而且它会“自信地出错”，误导忙碌的医生。所以医院让专科医生始终在回路里——软件建议，人做决定；患者也有权知道机器参与了多少。结论不是“人机对抗”，而是“人机协作”：机器快、不知疲倦、成本低，医生细致、有创造力、有温度，结合起来才能更早发现疾病，也让医生有时间多陪病人。", "src": "A Second Pair of Eyes: How AI Helps Doctors"}]}, {"set": 3, "date": "2026-09-29", "topic": "环境科普（湿地保护）", "title": "Wetlands: The Quiet Heroes of the Climate", "items": [{"p": "soak up", "cn": "吸收，吸走（水、热、知识等）", "eg": "When heavy rain falls, they soak up water that would otherwise flood towns downstream.", "egcn": "一提到应对气候变化，人们常想到森林和海洋，但真正最卖力的地方之一是湿地——水与土交汇的泥泞芦苇地。它像巨大的海绵：雨季蓄水防洪，旱季缓慢放水保供水；沿海湿地还能削弱风暴、保护家园。湿地的植物快速生长、死后沉入湿土缓慢分解，因此是极强的碳储库，一英亩沼泽的储碳量远超同面积森林；一旦被排干开发，这些碳就会被释放，加剧气候问题。过去百年间全球湿地大幅流失，但恢复是可行的，纽约、上海等城市正在重建沼泽、让河流恢复自然河道——尽管不便宜也不快，其清洁水源、安全海岸和更凉爽的地球等收益，值得社区投入。", "src": "Wetlands: The Quiet Heroes of the Climate"}, {"p": "in this way", "cn": "用这种方式，这样一来", "eg": "In this way, a single acre of marsh can hold far more carbon than the same area of forest.", "egcn": "一提到应对气候变化，人们常想到森林和海洋，但真正最卖力的地方之一是湿地——水与土交汇的泥泞芦苇地。它像巨大的海绵：雨季蓄水防洪，旱季缓慢放水保供水；沿海湿地还能削弱风暴、保护家园。湿地的植物快速生长、死后沉入湿土缓慢分解，因此是极强的碳储库，一英亩沼泽的储碳量远超同面积森林；一旦被排干开发，这些碳就会被释放，加剧气候问题。过去百年间全球湿地大幅流失，但恢复是可行的，纽约、上海等城市正在重建沼泽、让河流恢复自然河道——尽管不便宜也不快，其清洁水源、安全海岸和更凉爽的地球等收益，值得社区投入。", "src": "Wetlands: The Quiet Heroes of the Climate"}, {"p": "add to", "cn": "增加，加剧（问题、困难）", "eg": "His silence only added to our worry.", "egcn": "他的沉默只是加剧了我们的担忧。", "src": "Wetlands: The Quiet Heroes of the Climate"}, {"p": "natural tools for a warming world", "cn": "应对气候变暖的自然工具（可套用于环保写作）", "eg": "Today, scientists call them one of our best natural tools for a warming world.", "egcn": "一提到应对气候变化，人们常想到森林和海洋，但真正最卖力的地方之一是湿地——水与土交汇的泥泞芦苇地。它像巨大的海绵：雨季蓄水防洪，旱季缓慢放水保供水；沿海湿地还能削弱风暴、保护家园。湿地的植物快速生长、死后沉入湿土缓慢分解，因此是极强的碳储库，一英亩沼泽的储碳量远超同面积森林；一旦被排干开发，这些碳就会被释放，加剧气候问题。过去百年间全球湿地大幅流失，但恢复是可行的，纽约、上海等城市正在重建沼泽、让河流恢复自然河道——尽管不便宜也不快，其清洁水源、安全海岸和更凉爽的地球等收益，值得社区投入。", "src": "Wetlands: The Quiet Heroes of the Climate"}]}, {"set": 4, "date": "2026-09-30", "topic": "教育（劳动教育·校园菜园）", "title": "Learning by Doing: The Return of the School Garden", "items": [{"p": "a growing number of", "cn": "越来越多的（后接可数名词复数）", "eg": "A growing number of schools are trying to change that by handing students a small piece of land and a packet of seeds.", "egcn": "对今天许多孩子来说，番茄是超市里用塑料膜包好的东西。越来越多学校正试图改变这一点：把一小块地和一包种子交到学生手里。曾经在乡村常见的校园菜园，如今也在城市里悄然回归——而支持者坚称，它讲的其实根本不是蔬菜。菜园是不用课本的科学课：学生测量豆苗长得多快、测试院子哪一侧日照更足、琢磨为什么有的植物需要多得多水；他们也体会到自然缓慢的节奏——种子不关心截止日期，等第一株嫩芽冒头，对习惯了即时屏幕的孩子而言可能是最难的一课。老师还看到另一种收获：菜园不属于任何一个学生，浇水和除草必须分担，先干完的人学着去帮落后的人；平时极少发言的孩子，往往成了最先发现哪株植物渴了的人。有的学校把收获带进厨房，有的把多余蔬菜卖掉，再把钱投回工具和种子——无论哪种，道理都一样：付出与回报是连着的。但菜园并不好养：它需要空间、钱，更需要时间，而这三样在拥挤的学校里样样紧缺。临近考试，菜园往往第一个被忽视。因此有经验的老师主张，这类项目必须写进课表，而不是加在课表之上；只在好天气里活下来的菜园，恰恰教了最错的一课。", "src": "Learning by Doing: The Return of the School Garden"}, {"p": "work out", "cn": "弄明白，算出；解决", "eg": "Students measure how fast a bean sprout grows, test which side of the yard gets more sun, and work out why some plants need far more water than others.", "egcn": "对今天许多孩子来说，番茄是超市里用塑料膜包好的东西。越来越多学校正试图改变这一点：把一小块地和一包种子交到学生手里。曾经在乡村常见的校园菜园，如今也在城市里悄然回归——而支持者坚称，它讲的其实根本不是蔬菜。菜园是不用课本的科学课：学生测量豆苗长得多快、测试院子哪一侧日照更足、琢磨为什么有的植物需要多得多水；他们也体会到自然缓慢的节奏——种子不关心截止日期，等第一株嫩芽冒头，对习惯了即时屏幕的孩子而言可能是最难的一课。老师还看到另一种收获：菜园不属于任何一个学生，浇水和除草必须分担，先干完的人学着去帮落后的人；平时极少发言的孩子，往往成了最先发现哪株植物渴了的人。有的学校把收获带进厨房，有的把多余蔬菜卖掉，再把钱投回工具和种子——无论哪种，道理都一样：付出与回报是连着的。但菜园并不好养：它需要空间、钱，更需要时间，而这三样在拥挤的学校里样样紧缺。临近考试，菜园往往第一个被忽视。因此有经验的老师主张，这类项目必须写进课表，而不是加在课表之上；只在好天气里活下来的菜园，恰恰教了最错的一课。", "src": "Learning by Doing: The Return of the School Garden"}, {"p": "lag behind", "cn": "落后，落在后面", "eg": "A garden belongs to no single student, so watering and weeding have to be shared, and those who finish first learn to help the ones who lag behind.", "egcn": "对今天许多孩子来说，番茄是超市里用塑料膜包好的东西。越来越多学校正试图改变这一点：把一小块地和一包种子交到学生手里。曾经在乡村常见的校园菜园，如今也在城市里悄然回归——而支持者坚称，它讲的其实根本不是蔬菜。菜园是不用课本的科学课：学生测量豆苗长得多快、测试院子哪一侧日照更足、琢磨为什么有的植物需要多得多水；他们也体会到自然缓慢的节奏——种子不关心截止日期，等第一株嫩芽冒头，对习惯了即时屏幕的孩子而言可能是最难的一课。老师还看到另一种收获：菜园不属于任何一个学生，浇水和除草必须分担，先干完的人学着去帮落后的人；平时极少发言的孩子，往往成了最先发现哪株植物渴了的人。有的学校把收获带进厨房，有的把多余蔬菜卖掉，再把钱投回工具和种子——无论哪种，道理都一样：付出与回报是连着的。但菜园并不好养：它需要空间、钱，更需要时间，而这三样在拥挤的学校里样样紧缺。临近考试，菜园往往第一个被忽视。因此有经验的老师主张，这类项目必须写进课表，而不是加在课表之上；只在好天气里活下来的菜园，恰恰教了最错的一课。", "src": "Learning by Doing: The Return of the School Garden"}, {"p": "in short supply", "cn": "供应不足，短缺", "eg": "It needs space, money and, above all, time — three things that crowded schools have in short supply.", "egcn": "对今天许多孩子来说，番茄是超市里用塑料膜包好的东西。越来越多学校正试图改变这一点：把一小块地和一包种子交到学生手里。曾经在乡村常见的校园菜园，如今也在城市里悄然回归——而支持者坚称，它讲的其实根本不是蔬菜。菜园是不用课本的科学课：学生测量豆苗长得多快、测试院子哪一侧日照更足、琢磨为什么有的植物需要多得多水；他们也体会到自然缓慢的节奏——种子不关心截止日期，等第一株嫩芽冒头，对习惯了即时屏幕的孩子而言可能是最难的一课。老师还看到另一种收获：菜园不属于任何一个学生，浇水和除草必须分担，先干完的人学着去帮落后的人；平时极少发言的孩子，往往成了最先发现哪株植物渴了的人。有的学校把收获带进厨房，有的把多余蔬菜卖掉，再把钱投回工具和种子——无论哪种，道理都一样：付出与回报是连着的。但菜园并不好养：它需要空间、钱，更需要时间，而这三样在拥挤的学校里样样紧缺。临近考试，菜园往往第一个被忽视。因此有经验的老师主张，这类项目必须写进课表，而不是加在课表之上；只在好天气里活下来的菜园，恰恰教了最错的一课。", "src": "Learning by Doing: The Return of the School Garden"}, {"p": "rather than", "cn": "而不是（连接两个并列成分）", "eg": "For that reason, experienced teachers argue that such projects must be built into the timetable rather than added on top of it.", "egcn": "对今天许多孩子来说，番茄是超市里用塑料膜包好的东西。越来越多学校正试图改变这一点：把一小块地和一包种子交到学生手里。曾经在乡村常见的校园菜园，如今也在城市里悄然回归——而支持者坚称，它讲的其实根本不是蔬菜。菜园是不用课本的科学课：学生测量豆苗长得多快、测试院子哪一侧日照更足、琢磨为什么有的植物需要多得多水；他们也体会到自然缓慢的节奏——种子不关心截止日期，等第一株嫩芽冒头，对习惯了即时屏幕的孩子而言可能是最难的一课。老师还看到另一种收获：菜园不属于任何一个学生，浇水和除草必须分担，先干完的人学着去帮落后的人；平时极少发言的孩子，往往成了最先发现哪株植物渴了的人。有的学校把收获带进厨房，有的把多余蔬菜卖掉，再把钱投回工具和种子——无论哪种，道理都一样：付出与回报是连着的。但菜园并不好养：它需要空间、钱，更需要时间，而这三样在拥挤的学校里样样紧缺。临近考试，菜园往往第一个被忽视。因此有经验的老师主张，这类项目必须写进课表，而不是加在课表之上；只在好天气里活下来的菜园，恰恰教了最错的一课。", "src": "Learning by Doing: The Return of the School Garden"}]}, {"set": 5, "date": "2026-10-01", "topic": "经济（零工经济）", "title": "The Gig Economy: Freedom or Uncertainty?", "items": [{"p": "earn a living", "cn": "谋生，挣钱过日子", "eg": "Today, she may well earn a living by taking on short projects from an app.", "egcn": "十年前，大城市的年轻设计师通常会去公司找一份全职工作；如今，她很可能靠在手机上接短项目来谋生——这就是“零工经济”，它发展得惊人地快。它的吸引力在于自由：自己决定何时何地工作、可以同时接多个项目、一部手机一台电脑就能挣钱，对学生、家长和处于职业空档期的人来说尤其如此。但前景并非全然光明：多数零工不是雇员而是独立的承揽人，平台不给带薪假、病假和养老金，收入忽高忽低，一旦发生纠纷往往找不到明确的责任方。各国政府和平台正在寻找折中的办法，比如设立一种“中间身份”给予基本保障，或要求平台公开计酬方式。争论远未结束，但有一点很清楚：越多人以这种方式工作，保护他们的规则就越要跟上。", "src": "The Gig Economy: Freedom or Uncertainty?"}, {"p": "take on (a project)", "cn": "承接（项目）", "eg": "The firm took on a new project last month.", "egcn": "这家公司上个月承接了一个新项目。", "src": "The Gig Economy: Freedom or Uncertainty?"}, {"p": "keep pace (with)", "cn": "跟上（步伐），与……同步", "eg": "The debate is far from settled, but one thing is clear: as more people work this way, the rules that protect them must keep pace.", "egcn": "十年前，大城市的年轻设计师通常会去公司找一份全职工作；如今，她很可能靠在手机上接短项目来谋生——这就是“零工经济”，它发展得惊人地快。它的吸引力在于自由：自己决定何时何地工作、可以同时接多个项目、一部手机一台电脑就能挣钱，对学生、家长和处于职业空档期的人来说尤其如此。但前景并非全然光明：多数零工不是雇员而是独立的承揽人，平台不给带薪假、病假和养老金，收入忽高忽低，一旦发生纠纷往往找不到明确的责任方。各国政府和平台正在寻找折中的办法，比如设立一种“中间身份”给予基本保障，或要求平台公开计酬方式。争论远未结束，但有一点很清楚：越多人以这种方式工作，保护他们的规则就越要跟上。", "src": "The Gig Economy: Freedom or Uncertainty?"}, {"p": "nothing more than", "cn": "不过是，仅仅是", "eg": "Gig workers can choose when and where to work, take up several different projects at the same time, and earn money with nothing more than a phone and a laptop.", "egcn": "十年前，大城市的年轻设计师通常会去公司找一份全职工作；如今，她很可能靠在手机上接短项目来谋生——这就是“零工经济”，它发展得惊人地快。它的吸引力在于自由：自己决定何时何地工作、可以同时接多个项目、一部手机一台电脑就能挣钱，对学生、家长和处于职业空档期的人来说尤其如此。但前景并非全然光明：多数零工不是雇员而是独立的承揽人，平台不给带薪假、病假和养老金，收入忽高忽低，一旦发生纠纷往往找不到明确的责任方。各国政府和平台正在寻找折中的办法，比如设立一种“中间身份”给予基本保障，或要求平台公开计酬方式。争论远未结束，但有一点很清楚：越多人以这种方式工作，保护他们的规则就越要跟上。", "src": "The Gig Economy: Freedom or Uncertainty?"}]}, {"set": 6, "date": "2026-10-02", "topic": "社会（社区互助·时间银行）", "title": "Time Banking: Paying with Hours, Not Money", "items": [{"p": "instead of", "cn": "代替，而不是", "eg": "Instead of paying for help with money, neighbours pay with time.", "egcn": "在很多城市里，一种新的交换方式正在悄然兴起：邻居之间不用钱、而是用时间来支付帮助——这就是“时间银行”，它建立在一条简单规则上：你的一个小时，等于任何人的一个小时。它的运作是这样：当你花一小时帮别人（遛狗、修自行车、教一门语言），就获得一个“时间币”；日后你可以用它换取别人一小时的帮助。退休教师可以教数学，作为回报由年轻学生帮她整理花园。因为每个人的一小时都被视为等价，银行家和清洁工受到同样的对待。支持者说，时间银行不只是省钱：它把原本永不相识的人联结起来，也让市场常常忽视的技能（倾听、做饭，或者仅仅是耐心）有了价值；对老年人来说，它尤其既提供实际帮助，也给了他们保持活跃的理由。当然，时间银行并不完美：它依赖信任，小社区可能人手不够、难以满足所有需求，也有人担心一旦团体关闭、时间币就会作废。但对加入的人来说，回报往往超出实用层面——那是一种归属于某个“互相帮忙”的地方的感觉。", "src": "Time Banking: Paying with Hours, Not Money"}, {"p": "in return", "cn": "作为回报；作为交换", "eg": "A retired teacher may give maths lessons, and in return get her garden tidied by a young student.", "egcn": "在很多城市里，一种新的交换方式正在悄然兴起：邻居之间不用钱、而是用时间来支付帮助——这就是“时间银行”，它建立在一条简单规则上：你的一个小时，等于任何人的一个小时。它的运作是这样：当你花一小时帮别人（遛狗、修自行车、教一门语言），就获得一个“时间币”；日后你可以用它换取别人一小时的帮助。退休教师可以教数学，作为回报由年轻学生帮她整理花园。因为每个人的一小时都被视为等价，银行家和清洁工受到同样的对待。支持者说，时间银行不只是省钱：它把原本永不相识的人联结起来，也让市场常常忽视的技能（倾听、做饭，或者仅仅是耐心）有了价值；对老年人来说，它尤其既提供实际帮助，也给了他们保持活跃的理由。当然，时间银行并不完美：它依赖信任，小社区可能人手不够、难以满足所有需求，也有人担心一旦团体关闭、时间币就会作废。但对加入的人来说，回报往往超出实用层面——那是一种归属于某个“互相帮忙”的地方的感觉。", "src": "Time Banking: Paying with Hours, Not Money"}, {"p": "do more than", "cn": "不仅仅是（做……）", "eg": "Supporters say time banks do more than save money.", "egcn": "在很多城市里，一种新的交换方式正在悄然兴起：邻居之间不用钱、而是用时间来支付帮助——这就是“时间银行”，它建立在一条简单规则上：你的一个小时，等于任何人的一个小时。它的运作是这样：当你花一小时帮别人（遛狗、修自行车、教一门语言），就获得一个“时间币”；日后你可以用它换取别人一小时的帮助。退休教师可以教数学，作为回报由年轻学生帮她整理花园。因为每个人的一小时都被视为等价，银行家和清洁工受到同样的对待。支持者说，时间银行不只是省钱：它把原本永不相识的人联结起来，也让市场常常忽视的技能（倾听、做饭，或者仅仅是耐心）有了价值；对老年人来说，它尤其既提供实际帮助，也给了他们保持活跃的理由。当然，时间银行并不完美：它依赖信任，小社区可能人手不够、难以满足所有需求，也有人担心一旦团体关闭、时间币就会作废。但对加入的人来说，回报往往超出实用层面——那是一种归属于某个“互相帮忙”的地方的感觉。", "src": "Time Banking: Paying with Hours, Not Money"}, {"p": "flow in both directions", "cn": "双向流动", "eg": "On this street, traffic flows in both directions.", "egcn": "这条街上的车流是双向的。", "src": "Time Banking: Paying with Hours, Not Money"}]}, {"set": 7, "date": "2026-10-03", "topic": "健康科普（睡眠科学）", "title": "The Science of Sleep: Why Rest Is Productive", "items": [{"p": "far from", "cn": "远非，一点也不（后接动名词/形容词）", "eg": "Far from being idle, the sleeping body is busy repairing tissue, balancing hormones and strengthening the immune system.", "egcn": "多数人把睡眠当成“白天开始前被浪费掉”的时间，但科学研究给出了不同的答案：睡眠时大脑在整理白天的经历，保存重要的、清除多余的；身体则在修复组织、平衡激素、增强免疫。研究发现，睡眠不足不仅伤身，更拉低表现——每晚睡不足六小时的人反应更慢、错误更多、更容易生病；考前睡好的学生，记得远比熬夜的人多。夜里大脑还会清理白天积累的代谢废物，这一过程可能帮我们远离长期疾病。可见记忆不只是在学习时“写下”，更是在睡眠中“存好”。然而现代生活处处与休息为敌：屏幕深夜发亮、咖啡让人清醒、“随时在线”的压力让睡眠像奢侈品。熬夜赶工常等于把事做糟，还要付两遍代价。好消息是，改善睡眠只需简单几步：保持规律作息（周末也一样）、睡前调暗灯光、把手机请出卧室、把睡眠当作工作的一部分。在一个推崇忙碌的世界里，选择休息，也许正是最高效的决定。", "src": "The Science of Sleep: Why Rest Is Productive"}, {"p": "clear away", "cn": "清除，清理掉", "eg": "Please clear away the dishes after dinner.", "egcn": "晚饭后请把碗盘收走。", "src": "The Science of Sleep: Why Rest Is Productive"}, {"p": "work against", "cn": "对……不利，妨碍", "eg": "A tight deadline can work against good design.", "egcn": "紧迫的工期会妨碍好的设计。", "src": "The Science of Sleep: Why Rest Is Productive"}, {"p": "stay up (late)", "cn": "熬夜，不睡觉", "eg": "Don't stay up late the night before the exam.", "egcn": "考试前一晚别熬夜。", "src": "The Science of Sleep: Why Rest Is Productive"}, {"p": "pay for", "cn": "为……付出代价；付款", "eg": "Yet the habit of staying up late remains a poor bargain: we borrow a few hours of the night and pay for them with days of dull thinking and low spirits.", "egcn": "多数人把睡眠当成“白天开始前被浪费掉”的时间，但科学研究给出了不同的答案：睡眠时大脑在整理白天的经历，保存重要的、清除多余的；身体则在修复组织、平衡激素、增强免疫。研究发现，睡眠不足不仅伤身，更拉低表现——每晚睡不足六小时的人反应更慢、错误更多、更容易生病；考前睡好的学生，记得远比熬夜的人多。夜里大脑还会清理白天积累的代谢废物，这一过程可能帮我们远离长期疾病。可见记忆不只是在学习时“写下”，更是在睡眠中“存好”。然而现代生活处处与休息为敌：屏幕深夜发亮、咖啡让人清醒、“随时在线”的压力让睡眠像奢侈品。熬夜赶工常等于把事做糟，还要付两遍代价。好消息是，改善睡眠只需简单几步：保持规律作息（周末也一样）、睡前调暗灯光、把手机请出卧室、把睡眠当作工作的一部分。在一个推崇忙碌的世界里，选择休息，也许正是最高效的决定。", "src": "The Science of Sleep: Why Rest Is Productive"}]}, {"set": 8, "date": "2026-10-04", "topic": "文化（公共图书馆）", "title": "The Quiet Power of the Public Library", "items": [{"p": "belong to", "cn": "属于", "eg": "A library is more than a shelf of books; it is a promise that knowledge and quiet belong to all of us.", "egcn": "在几乎任何书都能在手机上找到的时代，有人怀疑公共图书馆是否还有意义。可走进任何一座城镇图书馆，答案就摆在眼前。图书馆的意义不只在书架上的书，更在于它提供了一个温暖、安全、免费、属于所有人的空间：不必消费，也无需安检，谁都能进来坐一坐。对独居或居家办公的人来说，这里甚至是一条“救命绳”；研究还表明，为兴趣而读书能减压、增强记忆。图书馆也在与时俱进：出借工具、开设免费课程、帮人填写线上表格，成了社区生活的一部分。当然，它也面临预算紧张等现实困难，但为省钱而砍掉图书馆往往得不偿失——它是一份“知识与安静属于每个人”的承诺，值得守护。", "src": "The Quiet Power of the Public Library"}, {"p": "fill in", "cn": "填写（表格 / 表格栏）", "eg": "Many now lend tools, run free classes and help people fill in official forms online.", "egcn": "在几乎任何书都能在手机上找到的时代，有人怀疑公共图书馆是否还有意义。可走进任何一座城镇图书馆，答案就摆在眼前。图书馆的意义不只在书架上的书，更在于它提供了一个温暖、安全、免费、属于所有人的空间：不必消费，也无需安检，谁都能进来坐一坐。对独居或居家办公的人来说，这里甚至是一条“救命绳”；研究还表明，为兴趣而读书能减压、增强记忆。图书馆也在与时俱进：出借工具、开设免费课程、帮人填写线上表格，成了社区生活的一部分。当然，它也面临预算紧张等现实困难，但为省钱而砍掉图书馆往往得不偿失——它是一份“知识与安静属于每个人”的承诺，值得守护。", "src": "The Quiet Power of the Public Library"}, {"p": "change with the times", "cn": "与时俱进", "eg": "A language must change with the times.", "egcn": "语言必须与时俱进。", "src": "The Quiet Power of the Public Library"}, {"p": "work from home", "cn": "居家办公", "eg": "For those who live alone or work from home, that space can be a lifeline.", "egcn": "在几乎任何书都能在手机上找到的时代，有人怀疑公共图书馆是否还有意义。可走进任何一座城镇图书馆，答案就摆在眼前。图书馆的意义不只在书架上的书，更在于它提供了一个温暖、安全、免费、属于所有人的空间：不必消费，也无需安检，谁都能进来坐一坐。对独居或居家办公的人来说，这里甚至是一条“救命绳”；研究还表明，为兴趣而读书能减压、增强记忆。图书馆也在与时俱进：出借工具、开设免费课程、帮人填写线上表格，成了社区生活的一部分。当然，它也面临预算紧张等现实困难，但为省钱而砍掉图书馆往往得不偿失——它是一份“知识与安静属于每个人”的承诺，值得守护。", "src": "The Quiet Power of the Public Library"}, {"p": "do more good than", "cn": "比……更有益处", "eg": "Studies even suggest that reading for pleasure lowers stress and improves memory, so an hour in the library may do more good than an hour of scrolling on a phone.", "egcn": "在几乎任何书都能在手机上找到的时代，有人怀疑公共图书馆是否还有意义。可走进任何一座城镇图书馆，答案就摆在眼前。图书馆的意义不只在书架上的书，更在于它提供了一个温暖、安全、免费、属于所有人的空间：不必消费，也无需安检，谁都能进来坐一坐。对独居或居家办公的人来说，这里甚至是一条“救命绳”；研究还表明，为兴趣而读书能减压、增强记忆。图书馆也在与时俱进：出借工具、开设免费课程、帮人填写线上表格，成了社区生活的一部分。当然，它也面临预算紧张等现实困难，但为省钱而砍掉图书馆往往得不偿失——它是一份“知识与安静属于每个人”的承诺，值得守护。", "src": "The Quiet Power of the Public Library"}]}, {"set": 9, "date": "2026-10-05", "topic": "人物小传（科学史）", "title": "The Woman Who Mapped the Ocean Floor", "items": [{"p": "set out to do sth", "cn": "着手做某事，打算做某事", "eg": "Marie Tharp did not set out to rewrite the history of the Earth.", "egcn": "玛丽·萨普起初并不是要改写地球的历史。她 1920 年生于密歇根，先学音乐、后学地质，那个年代进入科学界的女性寥寥无几。1948 年她搬到纽约，在哥伦比亚大学谋得一份绘制地图的工作。然而她不被允许随科考船出海——因为当时人们认为女人上船会带来厄运。", "src": "The Woman Who Mapped the Ocean Floor"}, {"p": "at first", "cn": "起初，起先", "eg": "Tharp's colleague Bruce Heezen at first dismissed her discovery as \"girl talk\".", "egcn": "这个发现意义重大。如果海底是沿着那条裂谷张开的，那么大陆果真可能在漂移——而这个想法当时仍被许多科学家嘲笑。萨普的同事布鲁斯·希森起初把她的发现斥为“女孩的闲话”。她只是继续一遍遍核对自己的工作。当证据再也无法被忽视时，他成了她最坚定的支持者之一，两人一起发表了一张改变我们看待这个星球方式的图。", "src": "The Woman Who Mapped the Ocean Floor"}, {"p": "no longer", "cn": "不再", "eg": "When the evidence could no longer be ignored, he became one of her strongest supporters, and together they published a map that changed how we see our planet.", "egcn": "这个发现意义重大。如果海底是沿着那条裂谷张开的，那么大陆果真可能在漂移——而这个想法当时仍被许多科学家嘲笑。萨普的同事布鲁斯·希森起初把她的发现斥为“女孩的闲话”。她只是继续一遍遍核对自己的工作。当证据再也无法被忽视时，他成了她最坚定的支持者之一，两人一起发表了一张改变我们看待这个星球方式的图。", "src": "The Woman Who Mapped the Ocean Floor"}, {"p": "a reminder that ...", "cn": "一个提醒：……（常用于结尾点题）", "eg": "Her story is a reminder that a great discovery may begin not with a ship, but with patience, a sharp pencil, and a refusal to stop asking questions.", "egcn": "萨普用了大约三十年描画那看不见的世界。1977 年，她的地图经艺术家海因里希·贝兰重绘后，出现在世界各地的教科书里。今天，许多人称她为现代海洋学的奠基人之一。她的故事提醒我们：一项伟大的发现，也许并非始于一艘船，而是始于耐心、一支削尖的铅笔，以及一颗不肯停止追问的心。", "src": "The Woman Who Mapped the Ocean Floor"}]}, {"set": 10, "date": "2026-10-06", "topic": "科技·航天探索", "title": "Return to the Moon: A New Space Race", "items": [{"p": "not only … but also …", "cn": "不仅……而且……（并列递进）", "eg": "Today the players are different: not only national space agencies but also private companies, and the goal is no longer to plant a flag and leave, but to stay.", "egcn": "五十多年来，人类再次准备踏上月球。20 世纪 60 年代的登月之争是超级大国之间的较量，政治与科学同样在推动它；而今天的参与方已大不相同——不只是各国航天机构，还有私营企业，目标也不再是插旗就走，而是留下来。", "src": "Return to the Moon: A New Space Race"}, {"p": "in other words", "cn": "换句话说，也就是说", "eg": "In other words, the Moon could become a kind of filling station on the long road to Mars.", "egcn": "计划颇为宏大。工程师们谈到要在月球南极附近建一座永久基地，那里的深坑在永久阴影中封存着水冰。这些冰可以融化成饮用水、分解出氧气供呼吸，还能制成火箭燃料——换句话说，月球可能成为通往火星路上的“加油站”。", "src": "Return to the Moon: A New Space Race"}, {"p": "point out", "cn": "指出，提出", "eg": "Critics point out that the same money could fund telescopes, medical research or efforts to fight climate change closer to home.", "egcn": "但并非所有人都信服。批评者指出，同样的钱本可以用于望远镜、医学研究，或在离地球更近的地方应对气候变化；他们还提醒，送人上太空远比送机器人昂贵和危险。支持者则回应，人类探索者能做到机器做不到的事，而且沿途研发的技术常常最终改善了地球上的日常生活。", "src": "Return to the Moon: A New Space Race"}, {"p": "end up doing sth", "cn": "最终变成做某事、以做某事告终", "eg": "We ended up walking home in the rain.", "egcn": "我们最后冒雨走回了家。", "src": "Return to the Moon: A New Space Race"}, {"p": "no longer … but …", "cn": "不再是……而是……", "eg": "He is no longer a student but a teacher.", "egcn": "他不再是学生，而是老师了。", "src": "Return to the Moon: A New Space Race"}]}, {"set": 11, "date": "2026-10-07", "topic": "环境科普·河流生态修复", "title": "The River That Came Back to Life", "items": [{"p": "little more than", "cn": "不过是，几乎只是", "eg": "For most of the twentieth century, the River Aire, which runs through a busy industrial city, was little more than an open sewer.", "egcn": "二十世纪的大部分时间里，穿过一座繁忙工业城市的艾尔河几乎就是一条露天下水道。工厂把染料和化学品排进河水，到 20 世纪 80 年代，河里几乎没有任何生物能够存活。", "src": "The River That Came Back to Life"}, {"p": "by accident", "cn": "偶然地，意外地", "eg": "The change did not happen by accident.", "egcn": "改变并非偶然。20 世纪 90 年代，当地政府先把污水净化后再排回河中，更严格的法律也迫使工厂停止倾倒废物；志愿者也加入进来，清理垃圾、沿岸种树。水一点点变清，小鱼也开始回来。", "src": "The River That Came Back to Life"}, {"p": "join in", "cn": "加入，参加", "eg": "Come and join in the game if you like.", "egcn": "喜欢的话就一起来玩这个游戏。", "src": "The River That Came Back to Life"}, {"p": "turn out to be", "cn": "结果是，原来是", "eg": "The stranger turned out to be my old classmate.", "egcn": "那个陌生人原来是我的老同学。", "src": "The River That Came Back to Life"}, {"p": "as well as", "cn": "也，以及（除…之外还有）", "eg": "Biologists who had once counted a handful of species now record more than forty kinds of fish, as well as otters, kingfishers and herons.", "egcn": "接着是野生动物的回归。曾经只能数出几种鱼的生物学家，如今记录到四十多种鱼，还有水獭、翠鸟和苍鹭。对这座城市来说，这条河成了散步、骑行和放松的好去处，河畔房产更值钱，岸边的咖啡馆每逢周末都很热闹。", "src": "The River That Came Back to Life"}]}, {"set": 12, "date": "2026-10-08", "topic": "科技·农业", "title": "Vertical Farms: Growing Up, Not Out", "items": [{"p": "around the clock", "cn": "昼夜不停地，全天候", "eg": "Special LED lamps replace sunlight, and computers control temperature, water and minerals around the clock.", "egcn": "到本世纪中叶，全球要养活近一百亿人，而可耕地却逐年减少。于是越来越多的工程师和创业者把目光转向室内：用层层叠叠的托盘、营养液和 LED 灯种植，不依赖土地与天气，这就是「垂直农业」。它比传统农业省水、少用农药、运输距离更近；但它耗电大、成本高，且只适合叶菜、香草、浆果等少数作物，能否真正推广还要看电从哪来。作者认为，随着城市扩张、农田萎缩，「向上种」或许是回答「如何养活所有人」的一条简单思路。", "src": "Vertical Farms: Growing Up, Not Out"}, {"p": "all year round", "cn": "一年到头", "eg": "Because the environment is fully controlled, a single room can produce the same amount as many hectares of open field, and it can do so all year round, whatever the weather outside.", "egcn": "到本世纪中叶，全球要养活近一百亿人，而可耕地却逐年减少。于是越来越多的工程师和创业者把目光转向室内：用层层叠叠的托盘、营养液和 LED 灯种植，不依赖土地与天气，这就是「垂直农业」。它比传统农业省水、少用农药、运输距离更近；但它耗电大、成本高，且只适合叶菜、香草、浆果等少数作物，能否真正推广还要看电从哪来。作者认为，随着城市扩张、农田萎缩，「向上种」或许是回答「如何养活所有人」的一条简单思路。", "src": "Vertical Farms: Growing Up, Not Out"}, {"p": "wear out", "cn": "（使）耗尽；（土壤）贫瘠", "eg": "Years of farming had worn out the soil.", "egcn": "多年耕作使这片土地贫瘠了。", "src": "Vertical Farms: Growing Up, Not Out"}, {"p": "rather than", "cn": "而不是", "eg": "Still, as cities grow and farmland shrinks, growing up rather than out may prove to be one of the simplest answers to an old question: how do we keep everyone fed?", "egcn": "到本世纪中叶，全球要养活近一百亿人，而可耕地却逐年减少。于是越来越多的工程师和创业者把目光转向室内：用层层叠叠的托盘、营养液和 LED 灯种植，不依赖土地与天气，这就是「垂直农业」。它比传统农业省水、少用农药、运输距离更近；但它耗电大、成本高，且只适合叶菜、香草、浆果等少数作物，能否真正推广还要看电从哪来。作者认为，随着城市扩张、农田萎缩，「向上种」或许是回答「如何养活所有人」的一条简单思路。", "src": "Vertical Farms: Growing Up, Not Out"}]}, {"set": 13, "date": "2026-10-09", "topic": "心理科普（行为科学·习惯养成）", "title": "Starting Small: The Science of Tiny Habits", "items": [{"p": "give up", "cn": "放弃", "eg": "Never give up hope, even in the hardest times.", "egcn": "即使在最难的时候也不要放弃希望。", "src": "Starting Small: The Science of Tiny Habits"}, {"p": "keep up (with sth)", "cn": "坚持；跟上", "eg": "It is that ambitious goals demand a level of effort and energy that few of us can keep up for long.", "egcn": "本文从『新年决心大多失败』说起：目标越大，第一步越难迈出。研究习惯的学者发现，持久的改变不靠一时的干劲，而靠把一个很小的动作反复重复，直到大脑几乎自动完成。据此很多人提倡『两分钟守则』——把起步动作缩到不可能失败，目的是在『意愿』和『行为』之间架桥，让大脑慢慢认定『这就是现在的我』。结论是：别依赖会耗尽的意志力，而要设计一个几乎能推着你走的日常习惯，改变往往是一点一点悄悄长出来的。", "src": "Starting Small: The Science of Tiny Habits"}, {"p": "run on its own", "cn": "自行运转", "eg": "After a week of training, the machine can run on its own.", "egcn": "经过一周的调试，这台机器能自行运转了。", "src": "Starting Small: The Science of Tiny Habits"}, {"p": "carry sb along", "cn": "推着某人前进；带动某人", "eg": "Her enthusiasm carried the whole team along.", "egcn": "她的热情带动了整个团队。", "src": "Starting Small: The Science of Tiny Habits"}]}, {"set": 14, "date": "2026-10-10", "topic": "体育（大众跑步·全民健身）", "title": "The Rise of the Weekend Marathon", "items": [{"p": "line up", "cn": "排队；列队", "eg": "Today, on almost any weekend, thousands of ordinary people line up at the start of a forty-two kilometre course.", "egcn": "本文从“马拉松不再是精英的专属”说起：随着收入提高、健康成为个人目标，跑步因装备少、易融入日常而迅速普及。规律运动能控制体重、强健心脏、降低多种疾病风险，还能带来清醒与平静。马拉松更演变为社交事件：朋友结伴训练、城市封路、路人加油，完成比赛与其说关乎速度，不如说是在实现个人目标。但专家提醒，热情须配以科学：训练要循序渐进，长跑之间注意恢复，忽视伤病信号往往要付出代价。结论是：持久的成果来自持续而适度的努力，而非一次爆发。", "src": "The Rise of the Weekend Marathon"}, {"p": "by chance", "cn": "偶然，碰巧", "eg": "The change did not happen by chance.", "egcn": "本文从“马拉松不再是精英的专属”说起：随着收入提高、健康成为个人目标，跑步因装备少、易融入日常而迅速普及。规律运动能控制体重、强健心脏、降低多种疾病风险，还能带来清醒与平静。马拉松更演变为社交事件：朋友结伴训练、城市封路、路人加油，完成比赛与其说关乎速度，不如说是在实现个人目标。但专家提醒，热情须配以科学：训练要循序渐进，长跑之间注意恢复，忽视伤病信号往往要付出代价。结论是：持久的成果来自持续而适度的努力，而非一次爆发。", "src": "The Rise of the Weekend Marathon"}, {"p": "point out", "cn": "指出", "eg": "Doctors point out that regular exercise is an effective way to control weight, strengthen the heart and lower the risk of many illnesses.", "egcn": "本文从“马拉松不再是精英的专属”说起：随着收入提高、健康成为个人目标，跑步因装备少、易融入日常而迅速普及。规律运动能控制体重、强健心脏、降低多种疾病风险，还能带来清醒与平静。马拉松更演变为社交事件：朋友结伴训练、城市封路、路人加油，完成比赛与其说关乎速度，不如说是在实现个人目标。但专家提醒，热情须配以科学：训练要循序渐进，长跑之间注意恢复，忽视伤病信号往往要付出代价。结论是：持久的成果来自持续而适度的努力，而非一次爆发。", "src": "The Rise of the Weekend Marathon"}, {"p": "pay for", "cn": "为……付出代价", "eg": "Runners who ignore the early signs of injury often pay for it later.", "egcn": "本文从“马拉松不再是精英的专属”说起：随着收入提高、健康成为个人目标，跑步因装备少、易融入日常而迅速普及。规律运动能控制体重、强健心脏、降低多种疾病风险，还能带来清醒与平静。马拉松更演变为社交事件：朋友结伴训练、城市封路、路人加油，完成比赛与其说关乎速度，不如说是在实现个人目标。但专家提醒，热情须配以科学：训练要循序渐进，长跑之间注意恢复，忽视伤病信号往往要付出代价。结论是：持久的成果来自持续而适度的努力，而非一次爆发。", "src": "The Rise of the Weekend Marathon"}]}, {"set": 15, "date": "2026-10-11", "topic": "教育·职业技能重塑", "title": "Reskilling in the Age of Automation", "items": [{"p": "hand over to", "cn": "把……交给（他人/机器）", "eg": "He will hand over the company to his daughter next year.", "egcn": "他明年会把公司交给女儿。", "src": "Reskilling in the Age of Automation"}, {"p": "little more than", "cn": "只不过是，无异于", "eg": "Critics warn that micro-credentials can become little more than colourful badges unless employers genuinely value them.", "egcn": "自动化与人工智能正以快于许多人适应的速度重塑职场：一项技能的“半衰期”已从“一辈子”缩短到几年，使再培训从边缘话题变为主流议题。压力分布并不均衡——重复性工作最先被机器接手，而做这些工作的人往往最没条件重新学习。各国政府和企业正在试验各种办法：资助短小、可叠加的证书，让成年人不必辞职或背债就能学到新技能；与社区学院合作开设晚间课程、提供带薪学习假，让学习变成持续的事。批评者提醒，若雇主不真正认可，微证书会沦为花哨的徽章；而且机会并不平等，最需要再培训的人常常最缺时间和金钱。但方向已少有争议：在工作几年一变的时代，持续学习的能力与机会，或许比任何单一的文凭都更重要。", "src": "Reskilling in the Age of Automation"}, {"p": "paid study leave", "cn": "带薪学习假", "eg": "Others build partnerships with community colleges, running evening classes and offering paid study leave.", "egcn": "自动化与人工智能正以快于许多人适应的速度重塑职场：一项技能的“半衰期”已从“一辈子”缩短到几年，使再培训从边缘话题变为主流议题。压力分布并不均衡——重复性工作最先被机器接手，而做这些工作的人往往最没条件重新学习。各国政府和企业正在试验各种办法：资助短小、可叠加的证书，让成年人不必辞职或背债就能学到新技能；与社区学院合作开设晚间课程、提供带薪学习假，让学习变成持续的事。批评者提醒，若雇主不真正认可，微证书会沦为花哨的徽章；而且机会并不平等，最需要再培训的人常常最缺时间和金钱。但方向已少有争议：在工作几年一变的时代，持续学习的能力与机会，或许比任何单一的文凭都更重要。", "src": "Reskilling in the Age of Automation"}, {"p": "the direction of travel", "cn": "总的发展方向", "eg": "Yet few disagree about the direction of travel.", "egcn": "自动化与人工智能正以快于许多人适应的速度重塑职场：一项技能的“半衰期”已从“一辈子”缩短到几年，使再培训从边缘话题变为主流议题。压力分布并不均衡——重复性工作最先被机器接手，而做这些工作的人往往最没条件重新学习。各国政府和企业正在试验各种办法：资助短小、可叠加的证书，让成年人不必辞职或背债就能学到新技能；与社区学院合作开设晚间课程、提供带薪学习假，让学习变成持续的事。批评者提醒，若雇主不真正认可，微证书会沦为花哨的徽章；而且机会并不平等，最需要再培训的人常常最缺时间和金钱。但方向已少有争议：在工作几年一变的时代，持续学习的能力与机会，或许比任何单一的文凭都更重要。", "src": "Reskilling in the Age of Automation"}]}, {"set": 16, "date": "2026-10-12", "topic": "科技·城市生活", "title": "Living in a Smarter City", "items": [{"p": "keep up (with)", "cn": "跟上，不落后", "eg": "As cities grow, they face a familiar set of problems: crowded roads, polluted air, and public services that struggle to keep up.", "egcn": "如今世界上一半以上的人口住在城市，预计到 2050 年这一比例将接近七成。城市越来越大，也面对同一组老问题：道路拥堵、空气污染、公共服务跟不上。于是许多政府转向技术找答案，希望数据能让城市生活更顺畅、更安全、更绿色。智慧城市的思路其实很简单：装在街道、公交和楼宇里的传感器收集交通、能耗和空气质量数据，汇总到统一平台，由程序找规律——某条路早上八点总堵，就调整红绿灯时长；某条公交几乎空跑，就重新设计线路；有些街区路灯在无人时自动调暗，既省钱又省电。但只有技术并不能让城市变聪明。批评者提醒：数据可能被滥用，摄像头可能把市民看得太紧，而较贫困的社区往往最后才享受到新服务。他们认为智慧城市必须建立在信任之上——人们要知道什么被采集、谁能看到、将如何使用；有些城市已开始公开数据，并请居民参与决定项目优先级。最成功的例子都把技术当成工具而不是目标：真正的问题不是一座城市装了多少传感器，而是市民是否因此过得更好——新系统若能让通勤者省下二十分钟、让一个家庭少交电费、或帮老人一键呼救，它就有了存在的价值。归根结底，城市只有愿意倾听才算聪明：听数据，更重要的是听住在里面的人。", "src": "Living in a Smarter City"}, {"p": "point out", "cn": "指出", "eg": "Critics point out that data can be misused, that cameras may watch citizens too closely, and that poorer neighborhoods are often the last to enjoy new services.", "egcn": "如今世界上一半以上的人口住在城市，预计到 2050 年这一比例将接近七成。城市越来越大，也面对同一组老问题：道路拥堵、空气污染、公共服务跟不上。于是许多政府转向技术找答案，希望数据能让城市生活更顺畅、更安全、更绿色。智慧城市的思路其实很简单：装在街道、公交和楼宇里的传感器收集交通、能耗和空气质量数据，汇总到统一平台，由程序找规律——某条路早上八点总堵，就调整红绿灯时长；某条公交几乎空跑，就重新设计线路；有些街区路灯在无人时自动调暗，既省钱又省电。但只有技术并不能让城市变聪明。批评者提醒：数据可能被滥用，摄像头可能把市民看得太紧，而较贫困的社区往往最后才享受到新服务。他们认为智慧城市必须建立在信任之上——人们要知道什么被采集、谁能看到、将如何使用；有些城市已开始公开数据，并请居民参与决定项目优先级。最成功的例子都把技术当成工具而不是目标：真正的问题不是一座城市装了多少传感器，而是市民是否因此过得更好——新系统若能让通勤者省下二十分钟、让一个家庭少交电费、或帮老人一键呼救，它就有了存在的价值。归根结底，城市只有愿意倾听才算聪明：听数据，更重要的是听住在里面的人。", "src": "Living in a Smarter City"}, {"p": "be built on", "cn": "建立在……之上", "eg": "A smart city, they argue, must be built on trust: people need to know what is being collected, who can see it, and how it will be used.", "egcn": "如今世界上一半以上的人口住在城市，预计到 2050 年这一比例将接近七成。城市越来越大，也面对同一组老问题：道路拥堵、空气污染、公共服务跟不上。于是许多政府转向技术找答案，希望数据能让城市生活更顺畅、更安全、更绿色。智慧城市的思路其实很简单：装在街道、公交和楼宇里的传感器收集交通、能耗和空气质量数据，汇总到统一平台，由程序找规律——某条路早上八点总堵，就调整红绿灯时长；某条公交几乎空跑，就重新设计线路；有些街区路灯在无人时自动调暗，既省钱又省电。但只有技术并不能让城市变聪明。批评者提醒：数据可能被滥用，摄像头可能把市民看得太紧，而较贫困的社区往往最后才享受到新服务。他们认为智慧城市必须建立在信任之上——人们要知道什么被采集、谁能看到、将如何使用；有些城市已开始公开数据，并请居民参与决定项目优先级。最成功的例子都把技术当成工具而不是目标：真正的问题不是一座城市装了多少传感器，而是市民是否因此过得更好——新系统若能让通勤者省下二十分钟、让一个家庭少交电费、或帮老人一键呼救，它就有了存在的价值。归根结底，城市只有愿意倾听才算聪明：听数据，更重要的是听住在里面的人。", "src": "Living in a Smarter City"}, {"p": "earn its place", "cn": "赢得一席之地，证明自己的价值", "eg": "This small shop has earned its place in the neighbourhood.", "egcn": "这家小店在社区里赢得了一席之地。", "src": "Living in a Smarter City"}]}, {"set": 17, "date": "2026-10-13", "topic": "人文历史", "title": "Paper: The Invention That Quietly Changed the World", "items": [{"p": "on a scale (the ancient world had never seen)", "cn": "以（古代世界从未见过的）规模", "eg": "There, in cities like Baghdad and Samarkand, paper mills multiplied, books became affordable, and scholars copied and compared texts on a scale the ancient world had never seen.", "egcn": "纸大约在公元一世纪诞生于中国，东汉蔡伦在公元105年改进了造纸工艺：把树皮、破布和鱼网浸泡打浆，压平晒干，做成又轻又便宜的书写材料。造纸术先东传朝鲜、日本，再沿商路西传，八世纪在巴格达、撒马尔罕等地出现造纸作坊，书籍因此变得便宜。此后经西班牙、意大利传入欧洲，打破了羊皮纸的垄断，阅读不再是少数富人的特权。十五世纪活字印刷术问世，廉价纸张与活字印刷合力推高了识字率，也让公共舆论逐渐成形。今天纸并未消失，它提醒我们：真正改变历史的技术，往往是最不起眼的那些。", "src": "Paper: The Invention That Quietly Changed the World"}, {"p": "take shape", "cn": "逐渐成形；初见轮廓", "eg": "The plan began to take shape after several meetings.", "egcn": "几次会议之后，计划开始成形。", "src": "Paper: The Invention That Quietly Changed the World"}, {"p": "loosen the grip of ...", "cn": "削弱、放松对……的掌控", "eg": "When the craft finally entered Europe, through Spain and later Italy, it helped loosen the grip of parchment, which had kept reading a luxury for the wealthy few.", "egcn": "纸大约在公元一世纪诞生于中国，东汉蔡伦在公元105年改进了造纸工艺：把树皮、破布和鱼网浸泡打浆，压平晒干，做成又轻又便宜的书写材料。造纸术先东传朝鲜、日本，再沿商路西传，八世纪在巴格达、撒马尔罕等地出现造纸作坊，书籍因此变得便宜。此后经西班牙、意大利传入欧洲，打破了羊皮纸的垄断，阅读不再是少数富人的特权。十五世纪活字印刷术问世，廉价纸张与活字印刷合力推高了识字率，也让公共舆论逐渐成形。今天纸并未消失，它提醒我们：真正改变历史的技术，往往是最不起眼的那些。", "src": "Paper: The Invention That Quietly Changed the World"}, {"p": "credit sb with sth", "cn": "把……归功于某人（同 be credited with）", "eg": "Scientists credit her with the discovery.", "egcn": "科学家们把这一发现归功于她。", "src": "Paper: The Invention That Quietly Changed the World"}]}, {"set": 18, "date": "2026-10-14", "topic": "艺术·音乐与大脑", "title": "The Science of Music: Why Songs Move Us", "items": [{"p": "light up", "cn": "点亮；使（面部、区域）明亮、活跃", "eg": "Melody and harmony light up regions linked to emotion, and familiar songs wake up the memory centres as well.", "egcn": "音乐无处不在，但很少有人想过一段旋律为何能让我们落泪、起舞或想起某个久远的夏天。脑成像研究发现，音乐不只刺激听觉区：节奏会激活控制运动的脑区，旋律与和声则点亮与情绪相关的区域，熟悉的歌还会唤醒记忆中枢——听音乐时几乎整个大脑都在参与。这也解释了为何学乐器有益：常练音乐的孩子在记忆与注意力任务中表现更好，成年人演奏或歌唱能减压、延缓衰老，而合唱、共舞等“与别人合拍”的行为还能增进信任与联结。当然，口味因人而异，但这种基本反应是普遍的——人天生就是热爱音乐的生物。", "src": "The Science of Music: Why Songs Move Us"}, {"p": "in time with", "cn": "与……合拍、同步", "eg": "Music also has a social power: singing in a choir or dancing at a festival helps people feel connected, because doing something in time with others builds trust and understanding.", "egcn": "音乐无处不在，但很少有人想过一段旋律为何能让我们落泪、起舞或想起某个久远的夏天。脑成像研究发现，音乐不只刺激听觉区：节奏会激活控制运动的脑区，旋律与和声则点亮与情绪相关的区域，熟悉的歌还会唤醒记忆中枢——听音乐时几乎整个大脑都在参与。这也解释了为何学乐器有益：常练音乐的孩子在记忆与注意力任务中表现更好，成年人演奏或歌唱能减压、延缓衰老，而合唱、共舞等“与别人合拍”的行为还能增进信任与联结。当然，口味因人而异，但这种基本反应是普遍的——人天生就是热爱音乐的生物。", "src": "The Science of Music: Why Songs Move Us"}, {"p": "far more than", "cn": "远不止；比……多得多", "eg": "Using brain scans, researchers have found that music stimulates far more than the hearing area.", "egcn": "音乐无处不在，但很少有人想过一段旋律为何能让我们落泪、起舞或想起某个久远的夏天。脑成像研究发现，音乐不只刺激听觉区：节奏会激活控制运动的脑区，旋律与和声则点亮与情绪相关的区域，熟悉的歌还会唤醒记忆中枢——听音乐时几乎整个大脑都在参与。这也解释了为何学乐器有益：常练音乐的孩子在记忆与注意力任务中表现更好，成年人演奏或歌唱能减压、延缓衰老，而合唱、共舞等“与别人合拍”的行为还能增进信任与联结。当然，口味因人而异，但这种基本反应是普遍的——人天生就是热爱音乐的生物。", "src": "The Science of Music: Why Songs Move Us"}, {"p": "slow the effects of", "cn": "减缓……的影响", "eg": "Trees help slow the effects of climate change.", "egcn": "树木有助于减缓气候变化的影响。", "src": "The Science of Music: Why Songs Move Us"}]}, {"set": 19, "date": "2026-10-15", "topic": "自然科普·野生动物（候鸟迁徙）", "title": "The Long Journey Home: How Birds Find Their Way", "items": [{"p": "find one's way", "cn": "找到路；寻路前行", "eg": "It took us an hour to find our way back to the hotel.", "egcn": "我们花了一小时才找到回旅馆的路。", "src": "The Long Journey Home: How Birds Find Their Way"}, {"p": "far from easy", "cn": "远非容易；一点也不简单", "eg": "The trip is far from easy.", "egcn": "每年秋天，数百万只候鸟离开繁殖地南飞越冬：小巧的莺要飞三千多公里，大雁则排成长队、彼此呼应着横越整片大陆。科学家发现鸟类同时使用多种导航工具——白天看太阳，夜里读星星，许多种类还能感知地球磁场，像自带一枚罗盘，年长的鸟还会记住河流、海岸、山峰等地标，让这场循环年复一年地精准重复。旅途并不轻松：要飞越海洋与沙漠、抵御风暴与捕猎，抵达目的地前体重可能减掉近一半，不少鸟死在途中；可许多幼鸟却能在从未走过这条路的情况下独自启程，靠的是本能而非记忆，它们的身体还会提前储存脂肪，像出远门前打点行囊的旅人。为什么要在意？因为候鸟把遥远的地方连在一起：它们传播种子、控制昆虫，是环境健康的活标志；数量下降就是在提醒我们沿途出了问题。科学家如今用微型标签和卫星追踪它们，但谜团仍然很多——正如蕾切尔·卡森所提醒的，愿意睁眼看自然的人永远不会真正孤单。", "src": "The Long Journey Home: How Birds Find Their Way"}, {"p": "set off", "cn": "出发，启程", "eg": "Yet the young of many species set off alone, without ever having made the journey before, guided by instinct rather than memory.", "egcn": "每年秋天，数百万只候鸟离开繁殖地南飞越冬：小巧的莺要飞三千多公里，大雁则排成长队、彼此呼应着横越整片大陆。科学家发现鸟类同时使用多种导航工具——白天看太阳，夜里读星星，许多种类还能感知地球磁场，像自带一枚罗盘，年长的鸟还会记住河流、海岸、山峰等地标，让这场循环年复一年地精准重复。旅途并不轻松：要飞越海洋与沙漠、抵御风暴与捕猎，抵达目的地前体重可能减掉近一半，不少鸟死在途中；可许多幼鸟却能在从未走过这条路的情况下独自启程，靠的是本能而非记忆，它们的身体还会提前储存脂肪，像出远门前打点行囊的旅人。为什么要在意？因为候鸟把遥远的地方连在一起：它们传播种子、控制昆虫，是环境健康的活标志；数量下降就是在提醒我们沿途出了问题。科学家如今用微型标签和卫星追踪它们，但谜团仍然很多——正如蕾切尔·卡森所提醒的，愿意睁眼看自然的人永远不会真正孤单。", "src": "The Long Journey Home: How Birds Find Their Way"}, {"p": "in advance", "cn": "提前，事先", "eg": "Their bodies change as well: they store extra fat in advance, exactly like a traveller packing for a long trip.", "egcn": "每年秋天，数百万只候鸟离开繁殖地南飞越冬：小巧的莺要飞三千多公里，大雁则排成长队、彼此呼应着横越整片大陆。科学家发现鸟类同时使用多种导航工具——白天看太阳，夜里读星星，许多种类还能感知地球磁场，像自带一枚罗盘，年长的鸟还会记住河流、海岸、山峰等地标，让这场循环年复一年地精准重复。旅途并不轻松：要飞越海洋与沙漠、抵御风暴与捕猎，抵达目的地前体重可能减掉近一半，不少鸟死在途中；可许多幼鸟却能在从未走过这条路的情况下独自启程，靠的是本能而非记忆，它们的身体还会提前储存脂肪，像出远门前打点行囊的旅人。为什么要在意？因为候鸟把遥远的地方连在一起：它们传播种子、控制昆虫，是环境健康的活标志；数量下降就是在提醒我们沿途出了问题。科学家如今用微型标签和卫星追踪它们，但谜团仍然很多——正如蕾切尔·卡森所提醒的，愿意睁眼看自然的人永远不会真正孤单。", "src": "The Long Journey Home: How Birds Find Their Way"}, {"p": "rather than", "cn": "而不是", "eg": "Yet the young of many species set off alone, without ever having made the journey before, guided by instinct rather than memory.", "egcn": "每年秋天，数百万只候鸟离开繁殖地南飞越冬：小巧的莺要飞三千多公里，大雁则排成长队、彼此呼应着横越整片大陆。科学家发现鸟类同时使用多种导航工具——白天看太阳，夜里读星星，许多种类还能感知地球磁场，像自带一枚罗盘，年长的鸟还会记住河流、海岸、山峰等地标，让这场循环年复一年地精准重复。旅途并不轻松：要飞越海洋与沙漠、抵御风暴与捕猎，抵达目的地前体重可能减掉近一半，不少鸟死在途中；可许多幼鸟却能在从未走过这条路的情况下独自启程，靠的是本能而非记忆，它们的身体还会提前储存脂肪，像出远门前打点行囊的旅人。为什么要在意？因为候鸟把遥远的地方连在一起：它们传播种子、控制昆虫，是环境健康的活标志；数量下降就是在提醒我们沿途出了问题。科学家如今用微型标签和卫星追踪它们，但谜团仍然很多——正如蕾切尔·卡森所提醒的，愿意睁眼看自然的人永远不会真正孤单。", "src": "The Long Journey Home: How Birds Find Their Way"}]}, {"set": 20, "date": "2026-10-16", "topic": "社会民生·老龄照护", "title": "Who Will Care for the Carers?", "items": [{"p": "around the clock", "cn": "昼夜不停，全天候", "eg": "These carers cook, clean, remind, lift and worry, often around the clock.", "egcn": "全球正快速老龄化，到 2050 年每六人中就有一位超过 65 岁。目前绝大多数长期照护是由家人（尤其是女性）无偿承担的，这份劳动省下了巨额公共开支，却几乎不计入经济统计。照护者的代价是放弃工作、承受压力与睡眠不足、甚至自己生病。西班牙、日本等已开始提供津贴、日间照料与短期“喘息”服务。经济学家的观点是：若照护者垮掉，国家要付出更高的医院与养老院成本。更深一层是文化问题——把老龄化当作私人的不幸，会悄悄惩罚那些撑着家庭的人；把它当作共同的责任，老人与照护者才能活得更好、更久。", "src": "Who Will Care for the Carers?"}, {"p": "give up", "cn": "放弃（工作、机会等）", "eg": "Carers are more likely to give up paid jobs, to suffer from stress and poor sleep, and to fall ill themselves.", "egcn": "全球正快速老龄化，到 2050 年每六人中就有一位超过 65 岁。目前绝大多数长期照护是由家人（尤其是女性）无偿承担的，这份劳动省下了巨额公共开支，却几乎不计入经济统计。照护者的代价是放弃工作、承受压力与睡眠不足、甚至自己生病。西班牙、日本等已开始提供津贴、日间照料与短期“喘息”服务。经济学家的观点是：若照护者垮掉，国家要付出更高的医院与养老院成本。更深一层是文化问题——把老龄化当作私人的不幸，会悄悄惩罚那些撑着家庭的人；把它当作共同的责任，老人与照护者才能活得更好、更久。", "src": "Who Will Care for the Carers?"}, {"p": "in the absence of", "cn": "在没有……的情况下", "eg": "In the absence of wider public help, some countries have begun to act: Spain offers family carers a monthly allowance, Japan runs subsidised day centres, and several cities fund short \"respite\" stays so that carers can rest.", "egcn": "全球正快速老龄化，到 2050 年每六人中就有一位超过 65 岁。目前绝大多数长期照护是由家人（尤其是女性）无偿承担的，这份劳动省下了巨额公共开支，却几乎不计入经济统计。照护者的代价是放弃工作、承受压力与睡眠不足、甚至自己生病。西班牙、日本等已开始提供津贴、日间照料与短期“喘息”服务。经济学家的观点是：若照护者垮掉，国家要付出更高的医院与养老院成本。更深一层是文化问题——把老龄化当作私人的不幸，会悄悄惩罚那些撑着家庭的人；把它当作共同的责任，老人与照护者才能活得更好、更久。", "src": "Who Will Care for the Carers?"}, {"p": "change hands", "cn": "（财物）易手，转手", "eg": "The old cafe has changed hands three times.", "egcn": "那家老咖啡馆已经转手三次了。", "src": "Who Will Care for the Carers?"}]}, {"set": 21, "date": "2026-10-17", "topic": "教育·学习方式", "title": "Why Handwriting Still Matters in a Digital Age", "items": [{"p": "put pen to paper", "cn": "提笔书写；落笔", "eg": "He finally put pen to paper and wrote her a letter.", "egcn": "他终于提笔给她写了封信。", "src": "Why Handwriting Still Matters in a Digital Age"}, {"p": "a growing body of research", "cn": "越来越多的研究", "eg": "Yet a growing body of research suggests that putting pen to paper still helps us learn, remember and think.", "egcn": "在一切都能敲进设备的时代，手写仍有助于学习与记忆。原因在于：打字太快，大脑来不及消化；手写较慢，逼人先判断重点，从而理解更深，记笔记的学生也往往记住更多要点。手写还能留下思考的痕迹——涂改、箭头、页边批注，都记录了想法的发展过程。文章并非主张放弃键盘，而是建议：追求速度时用键盘，追求理解和记忆时用手写。", "src": "Why Handwriting Still Matters in a Digital Age"}, {"p": "choose the right tool for the job", "cn": "为任务选对工具", "eg": "The wiser approach is to choose the right tool for the job: type when speed matters, but write by hand when the goal is to understand and remember.", "egcn": "在一切都能敲进设备的时代，手写仍有助于学习与记忆。原因在于：打字太快，大脑来不及消化；手写较慢，逼人先判断重点，从而理解更深，记笔记的学生也往往记住更多要点。手写还能留下思考的痕迹——涂改、箭头、页边批注，都记录了想法的发展过程。文章并非主张放弃键盘，而是建议：追求速度时用键盘，追求理解和记忆时用手写。", "src": "Why Handwriting Still Matters in a Digital Age"}, {"p": "take notes", "cn": "记笔记", "eg": "Studies of students have found that those who take notes by hand usually remember more of the key points than those who type.", "egcn": "在一切都能敲进设备的时代，手写仍有助于学习与记忆。原因在于：打字太快，大脑来不及消化；手写较慢，逼人先判断重点，从而理解更深，记笔记的学生也往往记住更多要点。手写还能留下思考的痕迹——涂改、箭头、页边批注，都记录了想法的发展过程。文章并非主张放弃键盘，而是建议：追求速度时用键盘，追求理解和记忆时用手写。", "src": "Why Handwriting Still Matters in a Digital Age"}]}, {"set": 22, "date": "2026-10-18", "topic": "科技·人工智能", "title": "AI in Everyday Life: From Helpers to Companions", "items": [{"p": "rely on", "cn": "依赖，依靠", "eg": "If students rely too heavily on AI for answers, their ability to think independently may weaken.", "egcn": "人工智能已从科幻走进日常：订天气、查路线、翻译聊天都在悄悄依赖它。学习和工作中，AI 像耐心的导师和高效的助手，让人专注于创造。但它也带来隐私泄露、过度依赖、数字鸿沟等担忧。关键在于平衡：把 AI 当工具而非替代，保持警惕、负责任地使用。", "src": "AI in Everyday Life: From Helpers to Companions"}, {"p": "play a bigger role in", "cn": "在…中发挥更大作用", "eg": "Local groups should play a bigger role in protecting the river.", "egcn": "地方组织应在保护这条河上发挥更大作用。", "src": "AI in Everyday Life: From Helpers to Companions"}, {"p": "focus on", "cn": "专注于", "eg": "As a result, people can focus on creative thinking while machines handle repetitive tasks.", "egcn": "人工智能已从科幻走进日常：订天气、查路线、翻译聊天都在悄悄依赖它。学习和工作中，AI 像耐心的导师和高效的助手，让人专注于创造。但它也带来隐私泄露、过度依赖、数字鸿沟等担忧。关键在于平衡：把 AI 当工具而非替代，保持警惕、负责任地使用。", "src": "AI in Everyday Life: From Helpers to Companions"}, {"p": "widen the gap between", "cn": "扩大…之间的差距", "eg": "Besides, not everyone has equal access to these powerful tools, which could widen the gap between rich and poor.", "egcn": "人工智能已从科幻走进日常：订天气、查路线、翻译聊天都在悄悄依赖它。学习和工作中，AI 像耐心的导师和高效的助手，让人专注于创造。但它也带来隐私泄露、过度依赖、数字鸿沟等担忧。关键在于平衡：把 AI 当工具而非替代，保持警惕、负责任地使用。", "src": "AI in Everyday Life: From Helpers to Companions"}]}, {"set": 23, "date": "2026-10-19", "topic": "健康科普（睡眠科学）", "title": "The Power of a Good Night's Sleep", "items": [{"p": "clear away", "cn": "清除，清理", "eg": "Please clear away the dishes after dinner.", "egcn": "晚饭后请把碗盘收走。", "src": "The Power of a Good Night's Sleep"}, {"p": "be linked to", "cn": "与…有关联", "eg": "The illness is linked to poor diet.", "egcn": "这种病与不良饮食有关。", "src": "The Power of a Good Night's Sleep"}, {"p": "at weekends", "cn": "在周末", "eg": "Experts suggest keeping a fixed schedule, even at weekends, and making the bedroom dark, cool, and quiet.", "egcn": "睡眠并不是忙碌日子的间隙，而是大脑和身体最活跃的时段之一：休息时大脑清除废物、肌肉修复、记忆得到强化，科学家把睡眠比作任何药物都无法替代的“夜间体检”。然而很多人睡眠不足，七小时以下在年轻人中超过半数，代价从注意力差、易怒到心脏病、肥胖和焦虑风险上升。好消息是睡眠质量可以通过固定作息、营造黑暗安静凉爽的环境、睡前远离咖啡和屏幕等简单习惯改善——手机蓝光会抑制褪黑素分泌。把睡眠当作投资而非浪费时间，它可能是学生、职场人最能建立的习惯。", "src": "The Power of a Good Night's Sleep"}, {"p": "with ease", "cn": "轻松地，不费力地", "eg": "A well-rested person learns faster, works more steadily, and handles pressure with greater ease.", "egcn": "睡眠并不是忙碌日子的间隙，而是大脑和身体最活跃的时段之一：休息时大脑清除废物、肌肉修复、记忆得到强化，科学家把睡眠比作任何药物都无法替代的“夜间体检”。然而很多人睡眠不足，七小时以下在年轻人中超过半数，代价从注意力差、易怒到心脏病、肥胖和焦虑风险上升。好消息是睡眠质量可以通过固定作息、营造黑暗安静凉爽的环境、睡前远离咖啡和屏幕等简单习惯改善——手机蓝光会抑制褪黑素分泌。把睡眠当作投资而非浪费时间，它可能是学生、职场人最能建立的习惯。", "src": "The Power of a Good Night's Sleep"}]}, {"set": 24, "date": "2026-10-20", "topic": "社会民生·志愿服务与青年成长", "title": "The Torch of Kindness: Why Volunteering Matters", "items": [{"p": "pick up the torch", "cn": "接过火炬，传承使命", "eg": "Every year, thousands of teenagers pick up the torch of volunteering.", "egcn": "每年都有成千上万的青少年接过志愿服务的火炬：给贫困村庄的孩子上课、看望孤独的老人、帮忙清理公园和河流。对许多人来说，这是他们走出校门后第一次体会责任。志愿者不图金钱与赞美，只想让身边的世界好一点点。年轻人为什么参与？有人把它当作成长的方式——在服务中学会包容不同的人、当众表达、解决意外问题；有人出于同理心，不忍他人受苦。原因不同，结果相同：给予者和接受者都收获良多。中国的一项研究发现，经常参加志愿服务的学生焦虑更少、目标感更强。志愿服务并不总是一帆风顺：新手会犹豫、会遇到敌意的目光、会因进展缓慢而绝望，但这些困难本身就是教育。正如谚语所说，成功属于那些一个个战胜小恐惧的人。最初的爱好会变成终身习惯，最初的笨拙会变成自信。在快速变化的世界里，善良是稳固的锚。志愿服务的火炬代代相传——从乡村教师到城市青年，从体育赛事到社区诊所。服务他人，也是在为自己建设一个更温暖、更公平的社会。这就是火焰永不熄灭的原因。", "src": "The Torch of Kindness: Why Volunteering Matters"}, {"p": "a sense of purpose", "cn": "目标感，使命感", "eg": "A study in China found that students who volunteer regularly report less anxiety and a stronger sense of purpose.", "egcn": "每年都有成千上万的青少年接过志愿服务的火炬：给贫困村庄的孩子上课、看望孤独的老人、帮忙清理公园和河流。对许多人来说，这是他们走出校门后第一次体会责任。志愿者不图金钱与赞美，只想让身边的世界好一点点。年轻人为什么参与？有人把它当作成长的方式——在服务中学会包容不同的人、当众表达、解决意外问题；有人出于同理心，不忍他人受苦。原因不同，结果相同：给予者和接受者都收获良多。中国的一项研究发现，经常参加志愿服务的学生焦虑更少、目标感更强。志愿服务并不总是一帆风顺：新手会犹豫、会遇到敌意的目光、会因进展缓慢而绝望，但这些困难本身就是教育。正如谚语所说，成功属于那些一个个战胜小恐惧的人。最初的爱好会变成终身习惯，最初的笨拙会变成自信。在快速变化的世界里，善良是稳固的锚。志愿服务的火炬代代相传——从乡村教师到城市青年，从体育赛事到社区诊所。服务他人，也是在为自己建设一个更温暖、更公平的社会。这就是火焰永不熄灭的原因。", "src": "The Torch of Kindness: Why Volunteering Matters"}, {"p": "one by one", "cn": "一个接一个地", "eg": "As the saying goes, success comes to those who conquer small fears one by one.", "egcn": "每年都有成千上万的青少年接过志愿服务的火炬：给贫困村庄的孩子上课、看望孤独的老人、帮忙清理公园和河流。对许多人来说，这是他们走出校门后第一次体会责任。志愿者不图金钱与赞美，只想让身边的世界好一点点。年轻人为什么参与？有人把它当作成长的方式——在服务中学会包容不同的人、当众表达、解决意外问题；有人出于同理心，不忍他人受苦。原因不同，结果相同：给予者和接受者都收获良多。中国的一项研究发现，经常参加志愿服务的学生焦虑更少、目标感更强。志愿服务并不总是一帆风顺：新手会犹豫、会遇到敌意的目光、会因进展缓慢而绝望，但这些困难本身就是教育。正如谚语所说，成功属于那些一个个战胜小恐惧的人。最初的爱好会变成终身习惯，最初的笨拙会变成自信。在快速变化的世界里，善良是稳固的锚。志愿服务的火炬代代相传——从乡村教师到城市青年，从体育赛事到社区诊所。服务他人，也是在为自己建设一个更温暖、更公平的社会。这就是火焰永不熄灭的原因。", "src": "The Torch of Kindness: Why Volunteering Matters"}, {"p": "from ... to ...", "cn": "从……到……（范围列举）", "eg": "The torch of volunteer service was passed from one generation to the next, from village teachers to city youth, from sports events to community clinics.", "egcn": "每年都有成千上万的青少年接过志愿服务的火炬：给贫困村庄的孩子上课、看望孤独的老人、帮忙清理公园和河流。对许多人来说，这是他们走出校门后第一次体会责任。志愿者不图金钱与赞美，只想让身边的世界好一点点。年轻人为什么参与？有人把它当作成长的方式——在服务中学会包容不同的人、当众表达、解决意外问题；有人出于同理心，不忍他人受苦。原因不同，结果相同：给予者和接受者都收获良多。中国的一项研究发现，经常参加志愿服务的学生焦虑更少、目标感更强。志愿服务并不总是一帆风顺：新手会犹豫、会遇到敌意的目光、会因进展缓慢而绝望，但这些困难本身就是教育。正如谚语所说，成功属于那些一个个战胜小恐惧的人。最初的爱好会变成终身习惯，最初的笨拙会变成自信。在快速变化的世界里，善良是稳固的锚。志愿服务的火炬代代相传——从乡村教师到城市青年，从体育赛事到社区诊所。服务他人，也是在为自己建设一个更温暖、更公平的社会。这就是火焰永不熄灭的原因。", "src": "The Torch of Kindness: Why Volunteering Matters"}]}, {"set": 25, "date": "2026-10-21", "topic": "科技创新·观察力与学习成长", "title": "The Eye That Notices: The Power of Observation", "items": [{"p": "depend on", "cn": "依赖，依靠", "eg": "Scientists, doctors and engineers all depend on this quiet ability to attract useful details from ordinary life.", "egcn": "每天我们从成百上千件小事旁边走过，却并没有真正看见它们。然而观察是一个人能够培养的最强大技能之一。好的观察者能看到别人错过的东西：天空中细微的变化、朋友不寻常的习惯、机器上的小瑕疵。科学家、医生和工程师都依赖这种安静的能力，从平凡生活中捕捉有用的细节。为什么观察如此重要？因为它是每一次发现的第一步。当牛顿看着苹果落下时，他看到的不是苹果，而是一个问题。观察引发好奇，好奇推动发明。在学校里，善于观察的学生往往更快理解知识，因为他们能看见抽象规则背后的客观事实。坚持关注细节的习惯能把普通人变成专家。观察可以像肌肉一样训练。一个实用的方法是每天暂停一分钟，详细描述周围的事物：叶子的颜色、书架上书的顺序、街道上的声音。另一种方法是随身带一个小本子，把打动你的三件事速写或记下来。几周之后，你会惊讶于自己的头脑变得多么敏锐。在这个充满屏幕和速度的时代，我们的注意力常常是分散的。学会观察就是学会慢下来，保持对世界的清醒意识。它让我们更明智、更有创造力、与他人联系更紧密。正如法国作家所说，真正的发现之旅不在于寻找新的风景，而在于拥有新的眼睛。所以，睁大你的眼睛——世界到处都是等待你的线索。", "src": "The Eye That Notices: The Power of Observation"}, {"p": "catch one's eye", "cn": "吸引某人的注意", "eg": "A bright red poster caught my eye.", "egcn": "一张鲜红的海报吸引了我的注意。", "src": "The Eye That Notices: The Power of Observation"}, {"p": "slow down", "cn": "放慢速度", "eg": "Learning to observe is learning to slow down and stay conscious of the world.", "egcn": "每天我们从成百上千件小事旁边走过，却并没有真正看见它们。然而观察是一个人能够培养的最强大技能之一。好的观察者能看到别人错过的东西：天空中细微的变化、朋友不寻常的习惯、机器上的小瑕疵。科学家、医生和工程师都依赖这种安静的能力，从平凡生活中捕捉有用的细节。为什么观察如此重要？因为它是每一次发现的第一步。当牛顿看着苹果落下时，他看到的不是苹果，而是一个问题。观察引发好奇，好奇推动发明。在学校里，善于观察的学生往往更快理解知识，因为他们能看见抽象规则背后的客观事实。坚持关注细节的习惯能把普通人变成专家。观察可以像肌肉一样训练。一个实用的方法是每天暂停一分钟，详细描述周围的事物：叶子的颜色、书架上书的顺序、街道上的声音。另一种方法是随身带一个小本子，把打动你的三件事速写或记下来。几周之后，你会惊讶于自己的头脑变得多么敏锐。在这个充满屏幕和速度的时代，我们的注意力常常是分散的。学会观察就是学会慢下来，保持对世界的清醒意识。它让我们更明智、更有创造力、与他人联系更紧密。正如法国作家所说，真正的发现之旅不在于寻找新的风景，而在于拥有新的眼睛。所以，睁大你的眼睛——世界到处都是等待你的线索。", "src": "The Eye That Notices: The Power of Observation"}, {"p": "turn ... into ...", "cn": "把……变成……", "eg": "A consistent habit of paying attention can turn a common person into a specialist.", "egcn": "每天我们从成百上千件小事旁边走过，却并没有真正看见它们。然而观察是一个人能够培养的最强大技能之一。好的观察者能看到别人错过的东西：天空中细微的变化、朋友不寻常的习惯、机器上的小瑕疵。科学家、医生和工程师都依赖这种安静的能力，从平凡生活中捕捉有用的细节。为什么观察如此重要？因为它是每一次发现的第一步。当牛顿看着苹果落下时，他看到的不是苹果，而是一个问题。观察引发好奇，好奇推动发明。在学校里，善于观察的学生往往更快理解知识，因为他们能看见抽象规则背后的客观事实。坚持关注细节的习惯能把普通人变成专家。观察可以像肌肉一样训练。一个实用的方法是每天暂停一分钟，详细描述周围的事物：叶子的颜色、书架上书的顺序、街道上的声音。另一种方法是随身带一个小本子，把打动你的三件事速写或记下来。几周之后，你会惊讶于自己的头脑变得多么敏锐。在这个充满屏幕和速度的时代，我们的注意力常常是分散的。学会观察就是学会慢下来，保持对世界的清醒意识。它让我们更明智、更有创造力、与他人联系更紧密。正如法国作家所说，真正的发现之旅不在于寻找新的风景，而在于拥有新的眼睛。所以，睁大你的眼睛——世界到处都是等待你的线索。", "src": "The Eye That Notices: The Power of Observation"}]}, {"set": 26, "date": "2026-10-22", "topic": "文化传承与现代生活", "title": "Traditions That Still Matter", "items": [{"p": "shape who we are", "cn": "塑造我们是谁（影响我们的身份）", "eg": "In a world of digital speed, traditions still shape who we are.", "egcn": "在数字速度的世界里，传统依然塑造着我们是谁。一个家庭的风俗、一块手工编织的布料、一个乡村节日：这些安静的习惯把我们与自己的来处相连。它们提醒我们来自哪里，并在生活艰难时给予指引。它们绝非多余，反而赋予日常生活一种和谐感与归属感。以谷物食品的制作为例。几个世纪以来，农民遵循同样的节奏：春天播种，秋天收获，与邻居分享收成。每一代人都添加一点属于自己的朴素内容，使这一做法的实质保持鲜活。学校和博物馆作为制度性机构，帮助保存这些传统并传递给年轻人。传统也出现在现代生活中。曾经把谷物从村庄运往城市的铁路，如今载着远离家乡的旅行者。祖母可能向孙女低声传授一道老菜谱，而工匠把一块普通搁板变成艺术品。这些记忆的丝线让我们的城市更丰富、更有人情味。没有它们，生活将失去多样性与魅力。当然，并非每种风俗都值得延续。一些旧习惯分裂人群，应当被勇敢地改变。明智的做法是保留有价值的东西，把其余交给诚实的审视。正如作曲家古斯塔夫·马勒所说：“传统不是对灰烬的崇拜，而是对火种的保存。”我们应当保存火种，而不是灰烬。", "src": "Traditions That Still Matter"}, {"p": "connect ... to ...", "cn": "把……与……连接起来", "eg": "A family custom, a hand-woven fabric, a village festival: these quiet habits connect us to our origin.", "egcn": "在数字速度的世界里，传统依然塑造着我们是谁。一个家庭的风俗、一块手工编织的布料、一个乡村节日：这些安静的习惯把我们与自己的来处相连。它们提醒我们来自哪里，并在生活艰难时给予指引。它们绝非多余，反而赋予日常生活一种和谐感与归属感。以谷物食品的制作为例。几个世纪以来，农民遵循同样的节奏：春天播种，秋天收获，与邻居分享收成。每一代人都添加一点属于自己的朴素内容，使这一做法的实质保持鲜活。学校和博物馆作为制度性机构，帮助保存这些传统并传递给年轻人。传统也出现在现代生活中。曾经把谷物从村庄运往城市的铁路，如今载着远离家乡的旅行者。祖母可能向孙女低声传授一道老菜谱，而工匠把一块普通搁板变成艺术品。这些记忆的丝线让我们的城市更丰富、更有人情味。没有它们，生活将失去多样性与魅力。当然，并非每种风俗都值得延续。一些旧习惯分裂人群，应当被勇敢地改变。明智的做法是保留有价值的东西，把其余交给诚实的审视。正如作曲家古斯塔夫·马勒所说：“传统不是对灰烬的崇拜，而是对火种的保存。”我们应当保存火种，而不是灰烬。", "src": "Traditions That Still Matter"}, {"p": "pass ... to ...", "cn": "把……传递给……", "eg": "Schools and museums, as institutions, help preserve such traditions and pass them to the young.", "egcn": "在数字速度的世界里，传统依然塑造着我们是谁。一个家庭的风俗、一块手工编织的布料、一个乡村节日：这些安静的习惯把我们与自己的来处相连。它们提醒我们来自哪里，并在生活艰难时给予指引。它们绝非多余，反而赋予日常生活一种和谐感与归属感。以谷物食品的制作为例。几个世纪以来，农民遵循同样的节奏：春天播种，秋天收获，与邻居分享收成。每一代人都添加一点属于自己的朴素内容，使这一做法的实质保持鲜活。学校和博物馆作为制度性机构，帮助保存这些传统并传递给年轻人。传统也出现在现代生活中。曾经把谷物从村庄运往城市的铁路，如今载着远离家乡的旅行者。祖母可能向孙女低声传授一道老菜谱，而工匠把一块普通搁板变成艺术品。这些记忆的丝线让我们的城市更丰富、更有人情味。没有它们，生活将失去多样性与魅力。当然，并非每种风俗都值得延续。一些旧习惯分裂人群，应当被勇敢地改变。明智的做法是保留有价值的东西，把其余交给诚实的审视。正如作曲家古斯塔夫·马勒所说：“传统不是对灰烬的崇拜，而是对火种的保存。”我们应当保存火种，而不是灰烬。", "src": "Traditions That Still Matter"}, {"p": "turn ... into ...", "cn": "把……变成……", "eg": "They turned the old factory into a museum.", "egcn": "他们把旧工厂变成了一座博物馆。", "src": "Traditions That Still Matter"}, {"p": "submit ... to ...", "cn": "把……提交给……（接受审查）", "eg": "The wise approach is to keep what is valuable and submit the rest to honest review.", "egcn": "在数字速度的世界里，传统依然塑造着我们是谁。一个家庭的风俗、一块手工编织的布料、一个乡村节日：这些安静的习惯把我们与自己的来处相连。它们提醒我们来自哪里，并在生活艰难时给予指引。它们绝非多余，反而赋予日常生活一种和谐感与归属感。以谷物食品的制作为例。几个世纪以来，农民遵循同样的节奏：春天播种，秋天收获，与邻居分享收成。每一代人都添加一点属于自己的朴素内容，使这一做法的实质保持鲜活。学校和博物馆作为制度性机构，帮助保存这些传统并传递给年轻人。传统也出现在现代生活中。曾经把谷物从村庄运往城市的铁路，如今载着远离家乡的旅行者。祖母可能向孙女低声传授一道老菜谱，而工匠把一块普通搁板变成艺术品。这些记忆的丝线让我们的城市更丰富、更有人情味。没有它们，生活将失去多样性与魅力。当然，并非每种风俗都值得延续。一些旧习惯分裂人群，应当被勇敢地改变。明智的做法是保留有价值的东西，把其余交给诚实的审视。正如作曲家古斯塔夫·马勒所说：“传统不是对灰烬的崇拜，而是对火种的保存。”我们应当保存火种，而不是灰烬。", "src": "Traditions That Still Matter"}]}, {"set": 27, "date": "2026-10-23", "topic": "经济（跨境电商·数字贸易）", "title": "Small Orders, a Big World: How Cross-border E-commerce Connects Us", "items": [{"p": "rest on", "cn": "依赖于；建立在…之上", "eg": "The whole argument rests on one weak assumption.", "egcn": "整个论证建立在一个薄弱的假设之上。", "src": "Small Orders, a Big World: How Cross-border E-commerce Connects Us"}, {"p": "cut out", "cn": "除去；省去（中间环节）", "eg": "You can cut out the middleman and sell online.", "egcn": "你可以省去中间商，直接在网上卖。", "src": "Small Orders, a Big World: How Cross-border E-commerce Connects Us"}, {"p": "lead to misunderstandings", "cn": "导致误解", "eg": "Different countries have different rules on taxes and product safety, and language and cultural gaps can lead to misunderstandings.", "egcn": "跨境电商让中国小商户的货物几天内就能送到外国顾客手中。它依靠三大支柱：平台连接买卖双方、物流网络缩短配送时间、在线支付保障交易安全。小企业无需出国开店就能面向全球销售，消费者也能享受更多选择和更低价格。当然，各国税制、产品标准差异以及语言文化隔阂仍是挑战，政府与平台正在携手完善规则。", "src": "Small Orders, a Big World: How Cross-border E-commerce Connects Us"}]}, {"set": 28, "date": "2026-10-24", "topic": "交通与环保（夜行列车复兴）", "title": "The Night Train Comes Back", "items": [{"p": "head for", "cn": "前往；驶向", "eg": "", "egcn": "夜行列车在欧洲复兴：从维也纳到罗马，睡一觉就到，省去机场排队、行李限制和清晨打车。推动力有三：政府对短途航班征税并补贴铁路；夜间卧铺常常比“机票加一晚酒店”更便宜；旅客在意飞行碳足迹，也享受伴着车轮声入睡。真正的障碍是现实成本——卧铺车厢造价和运营都贵、跨境速度慢、各国信号规则不同，不少线路亏钱，但运营商仍在订购新车，押注需求继续上升。能否活下来不靠怀旧而靠时刻表：只要准点发车、睡醒抵达，旅客就愿意接受慢一点。", "src": "The Night Train Comes Back"}, {"p": "be written off as", "cn": "被认为（不行了）而放弃", "eg": "", "egcn": "夜行列车在欧洲复兴：从维也纳到罗马，睡一觉就到，省去机场排队、行李限制和清晨打车。推动力有三：政府对短途航班征税并补贴铁路；夜间卧铺常常比“机票加一晚酒店”更便宜；旅客在意飞行碳足迹，也享受伴着车轮声入睡。真正的障碍是现实成本——卧铺车厢造价和运营都贵、跨境速度慢、各国信号规则不同，不少线路亏钱，但运营商仍在订购新车，押注需求继续上升。能否活下来不靠怀旧而靠时刻表：只要准点发车、睡醒抵达，旅客就愿意接受慢一点。", "src": "The Night Train Comes Back"}, {"p": "bet on", "cn": "押注；赌", "eg": "", "egcn": "夜行列车在欧洲复兴：从维也纳到罗马，睡一觉就到，省去机场排队、行李限制和清晨打车。推动力有三：政府对短途航班征税并补贴铁路；夜间卧铺常常比“机票加一晚酒店”更便宜；旅客在意飞行碳足迹，也享受伴着车轮声入睡。真正的障碍是现实成本——卧铺车厢造价和运营都贵、跨境速度慢、各国信号规则不同，不少线路亏钱，但运营商仍在订购新车，押注需求继续上升。能否活下来不靠怀旧而靠时刻表：只要准点发车、睡醒抵达，旅客就愿意接受慢一点。", "src": "The Night Train Comes Back"}]}, {"set": 29, "date": "2026-10-25", "topic": "文化（博物馆的互动化转型）", "title": "Why Museums Are Loosening Up", "items": [{"p": "keep one's hands to oneself", "cn": "不动手；不碰", "eg": "", "egcn": "过去的博物馆是“只看不动手”的地方，现在的博物馆希望你触摸、坐下、聆听甚至争论。策展人意识到注意力是稀缺资源：一屋子玻璃柜十五分钟就能看完，而一个有件大展品、一张长凳、墙上一句提问的厅却能让一家人待上一小时。于是博物馆展出更少的展品，给其余更多空间和更好的灯光。批评者担心这滑向纯娱乐，指出灯光秀比重新标注殖民藏品更容易拉到赞助；支持者回应说，好奇离场的观众会再来，疲惫离场的不会。最好的新博物馆两头都守住：用设计降低门槛，用学术抬高天花板。检验方法很简单——参观结束后，你还记得哪一件东西，并说得清它为什么重要。", "src": "Why Museums Are Loosening Up"}, {"p": "a scarce resource", "cn": "稀缺资源", "eg": "Curators have learned that attention is a scarce resource.", "egcn": "过去的博物馆是“只看不动手”的地方，现在的博物馆希望你触摸、坐下、聆听甚至争论。策展人意识到注意力是稀缺资源：一屋子玻璃柜十五分钟就能看完，而一个有件大展品、一张长凳、墙上一句提问的厅却能让一家人待上一小时。于是博物馆展出更少的展品，给其余更多空间和更好的灯光。批评者担心这滑向纯娱乐，指出灯光秀比重新标注殖民藏品更容易拉到赞助；支持者回应说，好奇离场的观众会再来，疲惫离场的不会。最好的新博物馆两头都守住：用设计降低门槛，用学术抬高天花板。检验方法很简单——参观结束后，你还记得哪一件东西，并说得清它为什么重要。", "src": "Why Museums Are Loosening Up"}, {"p": "drift towards", "cn": "逐渐滑向", "eg": "Critics warn of a drift towards pure entertainment.", "egcn": "过去的博物馆是“只看不动手”的地方，现在的博物馆希望你触摸、坐下、聆听甚至争论。策展人意识到注意力是稀缺资源：一屋子玻璃柜十五分钟就能看完，而一个有件大展品、一张长凳、墙上一句提问的厅却能让一家人待上一小时。于是博物馆展出更少的展品，给其余更多空间和更好的灯光。批评者担心这滑向纯娱乐，指出灯光秀比重新标注殖民藏品更容易拉到赞助；支持者回应说，好奇离场的观众会再来，疲惫离场的不会。最好的新博物馆两头都守住：用设计降低门槛，用学术抬高天花板。检验方法很简单——参观结束后，你还记得哪一件东西，并说得清它为什么重要。", "src": "Why Museums Are Loosening Up"}]}, {"set": 30, "date": "2026-10-26", "topic": "能源与乡村（光伏与储能）", "title": "The Village That Runs on Sunlight", "items": [{"p": "go dark", "cn": "停电；（灯）熄灭", "eg": "When a storm tore down the lines last winter, the village did not go dark.", "egcn": "这个四百人的村庄十年前每天只有六小时电，如今屋顶铺满光伏板，学校装了空调，诊所整夜能冷藏疫苗。变化不靠一个大工程，而靠许多小项目：电价下降后各家自己买板，合作社出钱买下共用电池，一位年轻工程师从城里回来负责维护。去年冬天风暴刮断线路时，村子没有断电。真正的难点不是阳光而是储能：正午阳光免费、夜里没有，所以需要电池，而电池需要有人每月检查；合作社每年培训两名村民，比请技术员飞来便宜得多。这不是技术童话，而是关于所有权的故事——当人们能看表、能修板、能算清省了多少钱，他们才会把系统当成自己的，而当成自己的东西往往能活得久。", "src": "The Village That Runs on Sunlight"}, {"p": "run the maintenance", "cn": "负责维护", "eg": "It came from many small ones: households bought panels as prices fell, a cooperative paid for a shared battery, and a young engineer came back from the city to run the maintenance.", "egcn": "这个四百人的村庄十年前每天只有六小时电，如今屋顶铺满光伏板，学校装了空调，诊所整夜能冷藏疫苗。变化不靠一个大工程，而靠许多小项目：电价下降后各家自己买板，合作社出钱买下共用电池，一位年轻工程师从城里回来负责维护。去年冬天风暴刮断线路时，村子没有断电。真正的难点不是阳光而是储能：正午阳光免费、夜里没有，所以需要电池，而电池需要有人每月检查；合作社每年培训两名村民，比请技术员飞来便宜得多。这不是技术童话，而是关于所有权的故事——当人们能看表、能修板、能算清省了多少钱，他们才会把系统当成自己的，而当成自己的东西往往能活得久。", "src": "The Village That Runs on Sunlight"}, {"p": "a fairy tale", "cn": "童话；不现实的故事", "eg": "What happened here is not a fairy tale about technology.", "egcn": "这个四百人的村庄十年前每天只有六小时电，如今屋顶铺满光伏板，学校装了空调，诊所整夜能冷藏疫苗。变化不靠一个大工程，而靠许多小项目：电价下降后各家自己买板，合作社出钱买下共用电池，一位年轻工程师从城里回来负责维护。去年冬天风暴刮断线路时，村子没有断电。真正的难点不是阳光而是储能：正午阳光免费、夜里没有，所以需要电池，而电池需要有人每月检查；合作社每年培训两名村民，比请技术员飞来便宜得多。这不是技术童话，而是关于所有权的故事——当人们能看表、能修板、能算清省了多少钱，他们才会把系统当成自己的，而当成自己的东西往往能活得久。", "src": "The Village That Runs on Sunlight"}]}, {"set": 31, "date": "2026-10-27", "topic": "社会民生（维修咖啡馆与消费习惯）", "title": "Repair Cafes: Fixing Things, and Habits", "items": [{"p": "out of sight", "cn": "看不见；视线之外", "eg": "Nothing is repaired out of sight, because the point is not only to fix a kettle but to remove the fear that makes people throw things away.", "egcn": "每月第一个周六，教堂后面的礼堂里堆满坏东西：闪个不停的台灯、烧不开的水壶、轮子变形的自行车。拿螺丝刀的志愿者坐在长桌旁，物主就坐在旁边。规矩很简单：带东西来、留下来、看着修。所有修理都在眼前进行，因为目的不只是修好一个水壶，而是消除那种“坏了就扔”的恐惧。厂商并不总是配合——胶粘外壳、异形螺丝、没有新电池就不肯运行的软件，让维修变得昂贵甚至毫无意义，于是有人推动立法强制企业多年供应备件，已有少数国家立法。维修咖啡馆不会逆转大生产，但它一家一家地改变算术：修好的水壶省钱，省下的水壶省一趟商店，而和志愿者度过的一个下午，比任何讲座都更能教会人什么叫消费。", "src": "Repair Cafes: Fixing Things, and Habits"}, {"p": "push for", "cn": "力争；推动（立法等）", "eg": "", "egcn": "每月第一个周六，教堂后面的礼堂里堆满坏东西：闪个不停的台灯、烧不开的水壶、轮子变形的自行车。拿螺丝刀的志愿者坐在长桌旁，物主就坐在旁边。规矩很简单：带东西来、留下来、看着修。所有修理都在眼前进行，因为目的不只是修好一个水壶，而是消除那种“坏了就扔”的恐惧。厂商并不总是配合——胶粘外壳、异形螺丝、没有新电池就不肯运行的软件，让维修变得昂贵甚至毫无意义，于是有人推动立法强制企业多年供应备件，已有少数国家立法。维修咖啡馆不会逆转大生产，但它一家一家地改变算术：修好的水壶省钱，省下的水壶省一趟商店，而和志愿者度过的一个下午，比任何讲座都更能教会人什么叫消费。", "src": "Repair Cafes: Fixing Things, and Habits"}, {"p": "spare parts", "cn": "备件；零配件", "eg": "Campaigners have pushed for laws that force companies to supply spare parts for years, and a few countries now require it.", "egcn": "每月第一个周六，教堂后面的礼堂里堆满坏东西：闪个不停的台灯、烧不开的水壶、轮子变形的自行车。拿螺丝刀的志愿者坐在长桌旁，物主就坐在旁边。规矩很简单：带东西来、留下来、看着修。所有修理都在眼前进行，因为目的不只是修好一个水壶，而是消除那种“坏了就扔”的恐惧。厂商并不总是配合——胶粘外壳、异形螺丝、没有新电池就不肯运行的软件，让维修变得昂贵甚至毫无意义，于是有人推动立法强制企业多年供应备件，已有少数国家立法。维修咖啡馆不会逆转大生产，但它一家一家地改变算术：修好的水壶省钱，省下的水壶省一趟商店，而和志愿者度过的一个下午，比任何讲座都更能教会人什么叫消费。", "src": "Repair Cafes: Fixing Things, and Habits"}]}, {"set": 32, "date": "2026-10-28", "topic": "环境科普（珊瑚礁修复）", "title": "The Long Road Back for Coral Reefs", "items": [{"p": "piece by piece", "cn": "一点一点地；逐块地", "eg": "A forest can be fenced and left alone; a reef must be rebuilt piece by piece, underwater, by divers working in short shifts.", "egcn": "修复珊瑚礁不像种树：森林可以围起来交给时间，珊瑚礁却必须由潜水员在水下一点一点重建。在印尼的一处潟湖，研究者搭起钢架，把珊瑚断枝绑上去，然后等待。存活取决于水温、取决于啃食海藻的鱼，也取决于下一个炎夏会不会来得太早；大约一半的断枝会死，活下来的会长成足以庇护小鱼群体的珊瑚丛。结论并不好受：修复很贵，而且无法按破坏的规模等比放大——一公顷重建的珊瑚礁，成本远高于一公顷被保护的珊瑚礁。保护虽然不光鲜，仍是最便宜的工具。不过钢架还有第二个用途：它给了当地人值得守护的东西。在靠礁糊口的村子，一个往钢架上绑过一万段珊瑚的潜水员，很难再去炸鱼。", "src": "The Long Road Back for Coral Reefs"}, {"p": "be scaled to", "cn": "按……的规模放大/调整", "eg": "The lesson is uncomfortable: restoration is expensive and cannot be scaled to the size of the damage.", "egcn": "修复珊瑚礁不像种树：森林可以围起来交给时间，珊瑚礁却必须由潜水员在水下一点一点重建。在印尼的一处潟湖，研究者搭起钢架，把珊瑚断枝绑上去，然后等待。存活取决于水温、取决于啃食海藻的鱼，也取决于下一个炎夏会不会来得太早；大约一半的断枝会死，活下来的会长成足以庇护小鱼群体的珊瑚丛。结论并不好受：修复很贵，而且无法按破坏的规模等比放大——一公顷重建的珊瑚礁，成本远高于一公顷被保护的珊瑚礁。保护虽然不光鲜，仍是最便宜的工具。不过钢架还有第二个用途：它给了当地人值得守护的东西。在靠礁糊口的村子，一个往钢架上绑过一万段珊瑚的潜水员，很难再去炸鱼。", "src": "The Long Road Back for Coral Reefs"}, {"p": "a poor candidate for", "cn": "不适合（做某事）的人", "eg": "In places where the reef feeds the village, a diver who has tied ten thousand fragments to a frame is a poor candidate for dynamite fishing.", "egcn": "修复珊瑚礁不像种树：森林可以围起来交给时间，珊瑚礁却必须由潜水员在水下一点一点重建。在印尼的一处潟湖，研究者搭起钢架，把珊瑚断枝绑上去，然后等待。存活取决于水温、取决于啃食海藻的鱼，也取决于下一个炎夏会不会来得太早；大约一半的断枝会死，活下来的会长成足以庇护小鱼群体的珊瑚丛。结论并不好受：修复很贵，而且无法按破坏的规模等比放大——一公顷重建的珊瑚礁，成本远高于一公顷被保护的珊瑚礁。保护虽然不光鲜，仍是最便宜的工具。不过钢架还有第二个用途：它给了当地人值得守护的东西。在靠礁糊口的村子，一个往钢架上绑过一万段珊瑚的潜水员，很难再去炸鱼。", "src": "The Long Road Back for Coral Reefs"}]}, {"set": 33, "date": "2026-10-29", "topic": "教育（沉浸式语言学习）", "title": "Learning a Language by Living It", "items": [{"p": "freeze", "cn": "（因紧张）僵住；愣住", "eg": "Most adults who study a foreign language for years still freeze when a waiter speaks quickly.", "egcn": "许多学了多年外语的成年人，一遇到服务员语速快就僵住。问题很少出在词汇量，而在于课堂把语言当成一门学科，而不是一件工具。把学生带出教室的老师看到的是另一种情形：一个必须自己买票、要发票、为晚点投诉的学生，一小时里就学会了三种句型，因为那几种句型是她拿到想要东西的唯一途径。沉浸也有代价：累、会出错，还会让习惯了自己很能干的成年人感到丢脸。好的项目会在一天结束时留出一小时“安全时间”，让学习者用母语提问、缓过来。可操作的建议很朴素：挑一件你本来就喜欢的每周活动，用外语去做——照外文菜谱做饭、听球赛解说、听你熟悉领域的播客。理解力总是在好奇心已经存在的地方长得最快。", "src": "Learning a Language by Living It"}, {"p": "build in", "cn": "内置；预留", "eg": "Good programmes build in a safe hour at the end of the day, when learners can ask questions in their own language and recover.", "egcn": "许多学了多年外语的成年人，一遇到服务员语速快就僵住。问题很少出在词汇量，而在于课堂把语言当成一门学科，而不是一件工具。把学生带出教室的老师看到的是另一种情形：一个必须自己买票、要发票、为晚点投诉的学生，一小时里就学会了三种句型，因为那几种句型是她拿到想要东西的唯一途径。沉浸也有代价：累、会出错，还会让习惯了自己很能干的成年人感到丢脸。好的项目会在一天结束时留出一小时“安全时间”，让学习者用母语提问、缓过来。可操作的建议很朴素：挑一件你本来就喜欢的每周活动，用外语去做——照外文菜谱做饭、听球赛解说、听你熟悉领域的播客。理解力总是在好奇心已经存在的地方长得最快。", "src": "Learning a Language by Living It"}, {"p": "be used to doing", "cn": "习惯于（做某事）", "eg": "", "egcn": "许多学了多年外语的成年人，一遇到服务员语速快就僵住。问题很少出在词汇量，而在于课堂把语言当成一门学科，而不是一件工具。把学生带出教室的老师看到的是另一种情形：一个必须自己买票、要发票、为晚点投诉的学生，一小时里就学会了三种句型，因为那几种句型是她拿到想要东西的唯一途径。沉浸也有代价：累、会出错，还会让习惯了自己很能干的成年人感到丢脸。好的项目会在一天结束时留出一小时“安全时间”，让学习者用母语提问、缓过来。可操作的建议很朴素：挑一件你本来就喜欢的每周活动，用外语去做——照外文菜谱做饭、听球赛解说、听你熟悉领域的播客。理解力总是在好奇心已经存在的地方长得最快。", "src": "Learning a Language by Living It"}]}, {"set": 34, "date": "2026-10-30", "topic": "经济（四天工作制实验）", "title": "The Rise of the Four-Day Week", "items": [{"p": "the catch", "cn": "问题在于；隐患", "eg": "The catch is that a shorter week is not a free gift.", "egcn": "2018 年新西兰一家小型软件公司试四天工作制时，所有人都以为会失败，结果产出反而上升：会议被砍、邮件链条变短，周一上班时大家有话说。此后数百家公司做过类似试验，结论相当一致：生产率持平或提高、病假减少、离职率下降，办公室、呼叫中心乃至少数工厂都成立。但关键在于，更短的工时不是白送的礼物，它要求删掉工作而不是压缩工作——把五天硬塞进四天的团队会抱怨压力大，然后悄悄回到五天；而取消例会、精简报告、保护整块专注时间的团队能把收益留住。这一模式能否走出知识型工作仍是未知：医院、餐馆、公交周五不能关门，它们可能演化出长班次、多员工、短年度的版本。但它背后的判断——工时是衡量价值很差的尺子——如今已难以否认。", "src": "The Rise of the Four-Day Week"}, {"p": "drift back", "cn": "慢慢退回原状", "eg": "Teams that simply squeeze five days into four report stress and quietly drift back.", "egcn": "2018 年新西兰一家小型软件公司试四天工作制时，所有人都以为会失败，结果产出反而上升：会议被砍、邮件链条变短，周一上班时大家有话说。此后数百家公司做过类似试验，结论相当一致：生产率持平或提高、病假减少、离职率下降，办公室、呼叫中心乃至少数工厂都成立。但关键在于，更短的工时不是白送的礼物，它要求删掉工作而不是压缩工作——把五天硬塞进四天的团队会抱怨压力大，然后悄悄回到五天；而取消例会、精简报告、保护整块专注时间的团队能把收益留住。这一模式能否走出知识型工作仍是未知：医院、餐馆、公交周五不能关门，它们可能演化出长班次、多员工、短年度的版本。但它背后的判断——工时是衡量价值很差的尺子——如今已难以否认。", "src": "The Rise of the Four-Day Week"}, {"p": "an open question", "cn": "尚无定论的问题", "eg": "Whether the model spreads beyond knowledge work is an open question.", "egcn": "2018 年新西兰一家小型软件公司试四天工作制时，所有人都以为会失败，结果产出反而上升：会议被砍、邮件链条变短，周一上班时大家有话说。此后数百家公司做过类似试验，结论相当一致：生产率持平或提高、病假减少、离职率下降，办公室、呼叫中心乃至少数工厂都成立。但关键在于，更短的工时不是白送的礼物，它要求删掉工作而不是压缩工作——把五天硬塞进四天的团队会抱怨压力大，然后悄悄回到五天；而取消例会、精简报告、保护整块专注时间的团队能把收益留住。这一模式能否走出知识型工作仍是未知：医院、餐馆、公交周五不能关门，它们可能演化出长班次、多员工、短年度的版本。但它背后的判断——工时是衡量价值很差的尺子——如今已难以否认。", "src": "The Rise of the Four-Day Week"}]}, {"set": 35, "date": "2026-10-31", "topic": "人文历史（地图的选择与偏见）", "title": "What Maps Hide", "items": [{"p": "in doing so", "cn": "这样做时；因此", "eg": "It selects, simplifies and ranks, and in doing so it tells you what to notice.", "egcn": "每张地图都是一个主张：它做选择、做简化、做排序，并因此告诉你该注意什么。教室里常见的墨卡托投影把格陵兰放大到看起来和非洲一样大——它适合导航，却几乎在别的所有方面误导人，一代学生带着扭曲的世界图像长大，角落里却没有一行字解释原因。数字地图用另一种方式隐藏：它优化“最快路线”，于是有学校的街道和空街看起来一模一样；它按热度排序，于是点评多的餐馆显眼，两条街外更好的一家却看不见。解决办法不是不要地图，而是会读地图：问是谁做的、为什么做、漏掉了什么。承认自己用途的地图是工具，假装自己就是世界的地图是陷阱。", "src": "What Maps Hide"}, {"p": "optimise for", "cn": "为……做优化", "eg": "They optimise for the fastest route, so a street with a school on it looks identical to an empty one.", "egcn": "每张地图都是一个主张：它做选择、做简化、做排序，并因此告诉你该注意什么。教室里常见的墨卡托投影把格陵兰放大到看起来和非洲一样大——它适合导航，却几乎在别的所有方面误导人，一代学生带着扭曲的世界图像长大，角落里却没有一行字解释原因。数字地图用另一种方式隐藏：它优化“最快路线”，于是有学校的街道和空街看起来一模一样；它按热度排序，于是点评多的餐馆显眼，两条街外更好的一家却看不见。解决办法不是不要地图，而是会读地图：问是谁做的、为什么做、漏掉了什么。承认自己用途的地图是工具，假装自己就是世界的地图是陷阱。", "src": "What Maps Hide"}, {"p": "leave out", "cn": "省略；遗漏", "eg": "", "egcn": "每张地图都是一个主张：它做选择、做简化、做排序，并因此告诉你该注意什么。教室里常见的墨卡托投影把格陵兰放大到看起来和非洲一样大——它适合导航，却几乎在别的所有方面误导人，一代学生带着扭曲的世界图像长大，角落里却没有一行字解释原因。数字地图用另一种方式隐藏：它优化“最快路线”，于是有学校的街道和空街看起来一模一样；它按热度排序，于是点评多的餐馆显眼，两条街外更好的一家却看不见。解决办法不是不要地图，而是会读地图：问是谁做的、为什么做、漏掉了什么。承认自己用途的地图是工具，假装自己就是世界的地图是陷阱。", "src": "What Maps Hide"}]}, {"set": 36, "date": "2026-11-01", "topic": "环境科普（城市野生蜂多样性）", "title": "Bees in the City", "items": [{"p": "hostile ground", "cn": "敌境；不利环境", "eg": "For most of the last century, the city was considered hostile ground for bees.", "egcn": "上世纪大部分时间，城市被视为蜜蜂的敌境：水泥、车流、农药似乎不留余地。但近年的调查推翻了这一假设——在欧洲几座城市，野生蜂的多样性甚至高于周边农田。原因是花：花园、阳台、铁路路基和墓园，从春到秋提供绵长（尽管破碎）的花期；而农田可能只提供两周的单一作物，然后就什么都没有。这并不是主张把农业都搬进城市：城市整体物种数仍然更少，城里的蜂依赖一张脆弱的绿地网络，一次预算决定就可能被剪断——一个新停车场就能抹掉十年的恢复。城市能做的既便宜又显眼：种本土花卉、少割草、留一块裸地给蜂筑巢、别把每株蒲公英都当杂草。一阳台薰衣草解决不了生物多样性丧失，但它是个开始留意的好地方。", "src": "Bees in the City"}, {"p": "by contrast", "cn": "相比之下", "eg": "Farmland, by contrast, may offer a single crop for two weeks and then nothing.", "egcn": "上世纪大部分时间，城市被视为蜜蜂的敌境：水泥、车流、农药似乎不留余地。但近年的调查推翻了这一假设——在欧洲几座城市，野生蜂的多样性甚至高于周边农田。原因是花：花园、阳台、铁路路基和墓园，从春到秋提供绵长（尽管破碎）的花期；而农田可能只提供两周的单一作物，然后就什么都没有。这并不是主张把农业都搬进城市：城市整体物种数仍然更少，城里的蜂依赖一张脆弱的绿地网络，一次预算决定就可能被剪断——一个新停车场就能抹掉十年的恢复。城市能做的既便宜又显眼：种本土花卉、少割草、留一块裸地给蜂筑巢、别把每株蒲公英都当杂草。一阳台薰衣草解决不了生物多样性丧失，但它是个开始留意的好地方。", "src": "Bees in the City"}, {"p": "a patch of", "cn": "一小块（地）", "eg": "What cities can do is cheap and visible: plant native flowers, mow less often, leave a patch of bare ground for nesting, and stop treating every dandelion as a weed.", "egcn": "上世纪大部分时间，城市被视为蜜蜂的敌境：水泥、车流、农药似乎不留余地。但近年的调查推翻了这一假设——在欧洲几座城市，野生蜂的多样性甚至高于周边农田。原因是花：花园、阳台、铁路路基和墓园，从春到秋提供绵长（尽管破碎）的花期；而农田可能只提供两周的单一作物，然后就什么都没有。这并不是主张把农业都搬进城市：城市整体物种数仍然更少，城里的蜂依赖一张脆弱的绿地网络，一次预算决定就可能被剪断——一个新停车场就能抹掉十年的恢复。城市能做的既便宜又显眼：种本土花卉、少割草、留一块裸地给蜂筑巢、别把每株蒲公英都当杂草。一阳台薰衣草解决不了生物多样性丧失，但它是个开始留意的好地方。", "src": "Bees in the City"}]}, {"set": 37, "date": "2026-11-02", "topic": "消费与电商（退货费用）", "title": "The Cost of Convenience: Return Fees", "items": [{"p": "a line item", "cn": "一项（账目）条目", "eg": "Now they are a line item that retailers are quietly deleting.", "egcn": "“免费退货”曾经是让顾客下单的承诺，如今成了零售商悄悄删掉的一行成本。退一个包裹并不免费，即使顾客一分钱不付：总有人要分拣、检查、重新包装，最后往往打折卖掉。在服装品类，真实退货成本可达商品价的三分之一，相当一部分退回的衣服被切碎或运往海外。零售商试过三种做法：收一点费用，抑制冲动购买；保持免费但拉长配送；或者用软件标记“惯犯”并悄悄限制，这已经引发诉讼。消费者的利益并不显然：收费惩罚的是因为尺码表出错而买了两个码的顾客。更好的办法在上游——准确的照片、诚实的尺寸、更少但做得更好的商品。由地球来买单的便利，其实并不便利。", "src": "The Cost of Convenience: Return Fees"}, {"p": "at a discount", "cn": "打折（出售）", "eg": "Someone sorts it, inspects it, repackages it, and often sells it at a discount.", "egcn": "“免费退货”曾经是让顾客下单的承诺，如今成了零售商悄悄删掉的一行成本。退一个包裹并不免费，即使顾客一分钱不付：总有人要分拣、检查、重新包装，最后往往打折卖掉。在服装品类，真实退货成本可达商品价的三分之一，相当一部分退回的衣服被切碎或运往海外。零售商试过三种做法：收一点费用，抑制冲动购买；保持免费但拉长配送；或者用软件标记“惯犯”并悄悄限制，这已经引发诉讼。消费者的利益并不显然：收费惩罚的是因为尺码表出错而买了两个码的顾客。更好的办法在上游——准确的照片、诚实的尺寸、更少但做得更好的商品。由地球来买单的便利，其实并不便利。", "src": "The Cost of Convenience: Return Fees"}, {"p": "upstream", "cn": "上游；源头环节", "eg": "The better fix is upstream: accurate photographs, honest measurements and fewer, better-made items.", "egcn": "“免费退货”曾经是让顾客下单的承诺，如今成了零售商悄悄删掉的一行成本。退一个包裹并不免费，即使顾客一分钱不付：总有人要分拣、检查、重新包装，最后往往打折卖掉。在服装品类，真实退货成本可达商品价的三分之一，相当一部分退回的衣服被切碎或运往海外。零售商试过三种做法：收一点费用，抑制冲动购买；保持免费但拉长配送；或者用软件标记“惯犯”并悄悄限制，这已经引发诉讼。消费者的利益并不显然：收费惩罚的是因为尺码表出错而买了两个码的顾客。更好的办法在上游——准确的照片、诚实的尺寸、更少但做得更好的商品。由地球来买单的便利，其实并不便利。", "src": "The Cost of Convenience: Return Fees"}]}, {"set": 38, "date": "2026-11-03", "topic": "社会民生（图书馆转型为社区空间）", "title": "A Library Without Silence", "items": [{"p": "far from doing", "cn": "非但不……（反而）", "eg": "", "egcn": "这家图书馆的阅览室很吵：孩子们为一副拼图争执，少年给朋友解释一段视频，两位退休老人讨论报纸标题，而馆员非但不“嘘”，还凑进去聊。这是有意为之：到馆人数连跌十年，管理层判断“安静”本身是问题的一部分——一个禁止喧哗的建筑，也禁止了大多数学习真正发生所需的那种对话。改造保留了旧阅览室给需要安静的人，把其余空间变成工作间：上烹饪课的厨房、放工具的角落、一个小舞台。借阅量上升了，更难量化的东西也上升了：图书馆成了人们“没有理由也会来”的地方。批评者说它是带书的社区中心；支持者回答，图书馆一直如此，书只是它最耐久的那一部分。在一个把孤独当作公共卫生问题的国家，一间温暖吵闹的房间，也许是图书馆能借出的最贵重的东西。", "src": "A Library Without Silence"}, {"p": "attach to", "cn": "附加于；附在……上", "eg": "", "egcn": "这家图书馆的阅览室很吵：孩子们为一副拼图争执，少年给朋友解释一段视频，两位退休老人讨论报纸标题，而馆员非但不“嘘”，还凑进去聊。这是有意为之：到馆人数连跌十年，管理层判断“安静”本身是问题的一部分——一个禁止喧哗的建筑，也禁止了大多数学习真正发生所需的那种对话。改造保留了旧阅览室给需要安静的人，把其余空间变成工作间：上烹饪课的厨房、放工具的角落、一个小舞台。借阅量上升了，更难量化的东西也上升了：图书馆成了人们“没有理由也会来”的地方。批评者说它是带书的社区中心；支持者回答，图书馆一直如此，书只是它最耐久的那一部分。在一个把孤独当作公共卫生问题的国家，一间温暖吵闹的房间，也许是图书馆能借出的最贵重的东西。", "src": "A Library Without Silence"}, {"p": "a public health problem", "cn": "公共卫生问题", "eg": "In a country where loneliness is now treated as a public health problem, a warm and noisy room may be the most valuable thing a library lends.", "egcn": "这家图书馆的阅览室很吵：孩子们为一副拼图争执，少年给朋友解释一段视频，两位退休老人讨论报纸标题，而馆员非但不“嘘”，还凑进去聊。这是有意为之：到馆人数连跌十年，管理层判断“安静”本身是问题的一部分——一个禁止喧哗的建筑，也禁止了大多数学习真正发生所需的那种对话。改造保留了旧阅览室给需要安静的人，把其余空间变成工作间：上烹饪课的厨房、放工具的角落、一个小舞台。借阅量上升了，更难量化的东西也上升了：图书馆成了人们“没有理由也会来”的地方。批评者说它是带书的社区中心；支持者回答，图书馆一直如此，书只是它最耐久的那一部分。在一个把孤独当作公共卫生问题的国家，一间温暖吵闹的房间，也许是图书馆能借出的最贵重的东西。", "src": "A Library Without Silence"}]}];
